			function company_lock_unlock()
			{
				global $con;
				$company_id = $_POST['company_id'];
				$current_state = $_POST['status'];
				if($current_state == 'Active')
				{
					$status = 'Closed';
				}
				else
				{
					$status = 'Active';
				};

				$query = "UPDATE `company` SET `status`='$status' WHERE `company_id`='$company_id'";
				mysqli_query($con,$query);
			}

