						$data .= '</select>
						<select class="form-control" name="validation_sheet_item_idD" id="validation_sheet_item_idD" disabled="true"> 
							<option value="0">Please Select</option>';
							
							$sql="SELECT * FROM surgery WHERE surgery_id='$item_id'";
							$result=mysqli_query($con,$sql);
								while($row=mysqli_fetch_array($result))
								{
									if($row['surgery_id'] == $item_id)
									{
										$data .= '<option value = "'.$row['surgery_id'].'" selected="selected">'.$row['surgery'].'</option>';
									}
									else
									{
										$data .= '<option value = "'.$row['surgery_id'].'">'.$row['surgery'].'</option>';
									};
								};
						
						$data .= '</select>';
					};
				echo $data;
			}

			function save_validation_sheet()
