			function delete_diagnosis()
			{
				global $con;
				$diagnosis_id = $_POST['diagnosis_id'];
			    
			    $query = "SELECT * FROM `diagnosis_list` WHERE `diagnosis_id`='$diagnosis_id'";
			    $query_run = mysqli_query($con, $query);
				if(mysqli_num_rows($query_run) < 1)
				{
			    	$query = "DELETE FROM `diagnosis` WHERE `diagnosis_id`='$diagnosis_id'";
			    	mysqli_query($con, $query);
					echo 'deleted';
				}
				else
				{
					echo 'used';
				};
			}
			
			function diagnosis_merge_duplicate()
			{
				global $con;
				$diagnosis_id_from = $_POST['diagnosis_merge_duplicate_from'];
				$diagnosis_id_to = $_POST['diagnosis_merge_duplicate_to'];
			    
			    $query = "UPDATE `diagnosis_list`SET `diagnosis_id`='$diagnosis_id_to' WHERE `diagnosis_id`='$diagnosis_id_from'";
			    mysqli_query($con, $query);
			    $query = "UPDATE `stat_incidence_of_diseases`SET `diagnosis_id`='$diagnosis_id_to' WHERE `diagnosis_id`='$diagnosis_id_from'";
			    mysqli_query($con, $query);
			    $query = "DELETE FROM `diagnosis` WHERE `diagnosis_id`='$diagnosis_id_from'";
			    mysqli_query($con, $query);
			}
