			    $query = "INSERT INTO `drugs`(`nhis_id`, `brand_name`, `generic_name`,`code`, 
				`type`, `class`,`category`, `unit`, `manufacturer`,`price_cash`,`price_cash_foreign`, 
				`price_nhis`, `price_prvt`,`age_from`, `age_to`, `gender`,`block_neg`, `expiry_date`, 
				`batch`, `days_prompt`, `route`, `company_id`, `branch_id`, `created_by`, `created_datetime`,
				`price_nhis_topup`, `unit_2`, `unit_qty`, `unit_2_qty`, `item_origin`, `item_group`, 
				`price_wholesale`, `price_retail`) 
				VALUES ('$nhisitem','$brand_name','$generic_name', '$code','$type','$classification',
				'$category','$unit_of_measure','$manufacturer', '$price_cash','$price_cash_foreign',
