			function customer_save()
			{
				global $con;
				$customer_id = $_POST['customer_id'];
				$customer_first_name = $_POST['customer_first_name'];
				$customer_last_name = $_POST['customer_last_name'];
				$customer_sex = $_POST['customer_sex'];
				$customer_dob = $_POST['customer_dob'];
				$customer_email = $_POST['customer_email'];
				$customer_phone_number = $_POST['customer_phone_number'];
				$customer_id_number = $_POST['customer_id_number'];
				$customer_id_type = $_POST['customer_id_type'];
				$customer_marital_status = $_POST['customer_marital_status'];
				$customer_address = $_POST['customer_address'];
				$customer_location = $_POST['customer_location'];
				$customer_religion = $_POST['customer_religion'];
				$customer_occupation = $_POST['customer_occupation'];
				$customer_other_info = $_POST['customer_other_info'];
				$customer_allergies = $_POST['customer_allergies'];
				$customer_entry_type = $_POST['customer_entry_type'];

				$company_id = $_SESSION['company_id'];
				$branch_id = $_SESSION['branch_id'];
				$user_id = $_SESSION['user_id'];

				$query = "INSERT INTO `customer`(`company_id`,`branch_id`,`user_id`,`first_name`,
				`last_name`,`date_of_birth`,`phone_number`,`address`,`location`,`email`,
				`marital_status`,`gender`,`occupation`,`religion`,`id_number`,`id_type`,
				`other_info`,`allergies`,`created_by`,`created_datetime`) VALUES ('$company_id',
				'$branch_id','$user_id','$customer_first_name','$customer_last_name',
				'$customer_dob','$customer_phone_number','$customer_address','$customer_location',
				'$customer_email','$customer_marital_status','$customer_sex','$customer_occupation',
				'$customer_religion','$customer_id_number','$customer_id_type','$customer_other_info',
				'$customer_allergies','$user_id',NOW())";
				$query_run = mysqli_query($con,$query);

				if($query_run)
				{
					$query_select = "SELECT * FROM customer ORDER BY customer_id DESC";
					$query_run_select = mysqli_query($con,$query_select);
					$row_select = mysqli_fetch_assoc($query_run_select);
					$customer_id = $row_select['customer_id'];

					echo '<table class="table table-hover table-bordered table-sm" id="stock_sales_invoice_customer_detailsTable" width="100%" cellspacing="0">
						<thead>
							<tr>
								<td><strong>Name</strong></td>
								<td colspan="2">'.$customer_first_name.' '.$customer_last_name.'</td>
								<input type="hidden" class="form-control" name="stock_sales_invoice_customer_name" id="stock_sales_invoice_customer_name" value="'.$customer_first_name.' '.$customer_last_name.'">
								<input type="hidden" class="form-control" name="stock_sales_invoice_customer_id" id="stock_sales_invoice_customer_id" value="'.$customer_id.'">
								<input type="hidden" class="form-control" name="stock_sales_invoice_customer_age" id="stock_sales_invoice_customer_age" value="'.ageCalculator($customer_dob).'">
								<input type="hidden" class="form-control" name="stock_sales_invoice_customer_id_number" id="stock_sales_invoice_customer_id_number" value="'.$customer_id_number.'">
								<input type="hidden" class="form-control" name="stock_sales_invoice_customer_gender" id="stock_sales_invoice_customer_gender" value="'.$customer_sex.'">
								<td class="action-td">
									<a href="#" data-toggle="" data-id="invoice" id="new_customer_icon">New</a>
									| 
									<a href="#" data-toggle="" id="search_customer_icon">Search</a>
								</td>
							</tr>
							<tr>
								<td><strong>Age</strong></td>
								<td>'.ageCalculator($customer_dob).' YRS</td>
								<td><strong>Phone No:</strong></td>
								<td>'.$customer_phone_number.'</td>
							</tr>
							<tr>
								<td><strong>Sex</strong></td>
								<td>'.$customer_sex.'</td>
								<td><strong>ID No:</strong></td>
								<td>'.$customer_id_number.'</td>
							</tr>
						</thead>
					</table>';
				};
			}

