			function save_new_stock_item()
			{
				global $con;
				$stock_item_name = addslashes($_POST['stock_item_name']);
				$stock_item_code = $_POST['stock_item_code'];
				$unit_of_measure = $_POST['unit_of_measure'];
				$unit_of_measure_retail = $_POST['unit_of_measure_retail'];
