			function save_price_list_auto()
			{
				global $con;
				ini_set('max_execution_time', '600');
				$company_id = $_SESSION['company_id'];
				$price_level_id = $_POST['price_list_auto_price_level_id'];
				$_SESSION['price_level_id'] = $_POST['price_list_auto_price_level_id'];
				$group = $_POST['price_list_auto_group'];
				$type = $_POST['price_list_auto_type'];
				$amount = $_POST['price_list_auto_amount'];
				$user_id = $_SESSION['user_id'];

				if(isset($_SESSION['margin_branch'])){$margin_branch = $_SESSION['margin_branch'];}else{$margin_branch = 0;};
				if(isset($_SESSION['margin_inter_branch'])){$margin_inter_branch = $_SESSION['margin_inter_branch'];}else{$margin_inter_branch = 0;};
				if(isset($_SESSION['margin_insurance'])){$margin_insurance = $_SESSION['margin_insurance'];}else{$margin_insurance = 0;};

				if($group == 'ALL')
				{
					$query = "SELECT * FROM price_list WHERE `price_level_id`='$price_level_id'";
				}
				else
				{
					$query = "SELECT l.* FROM price_list l JOIN stock_item s ON l.stock_item_id=s.stock_item_id
					WHERE `l.price_level_id`='$price_level_id' AND s.stock_item_type_id='$group'";
				};
				$result = mysqli_query($con,$query); 
				while($row = mysqli_fetch_assoc($result))  
				{  
					$price_list_id = $row['price_list_id'];
					$price = $row['price'];
					
					if($type =='Increase_By_Percentage')
					{
						$cash_price = $price + round($price * $amount);
					}
					else if($type =='Decrease_By_Percentage')
					{
						$cash_price = $price - round($price * $amount);
					}
					else if($type =='Increase_By_Amount')
					{
						$cash_price = $price + $amount;
					}
					else if($type =='Decrease_By_Amount')
					{
						$cash_price = $price - $amount;
					};

					if($margin_inter_branch > 0)
					{$branch_price = $cash_price - round($cash_price * $margin_inter_branch);}else{$branch_price = 0;};

					if($margin_insurance > 0)
					{$insurance_price = $cash_price + round($cash_price * $margin_insurance);}else{$insurance_price = 0;};

					if($cash_price > 0) 
					{
						$query_pl = "UPDATE `price_list`SET `price`='$cash_price',`price_branch`='$branch_price', 
						`price_insurance`='$insurance_price' WHERE `price_list_id`= '$price_list_id'";
						mysqli_query($con, $query_pl);
					};
				};
			}

