			}

			function edit_patient_age()
			{
				global $con;
				$patient_id = $_POST['patient_id'];
				$attend_id = $_POST['attend_id'];
				$Patient_Data=array();
				$query = "SELECT age FROM attendance WHERE attend_id='$attend_id'";
				$result_age = mysqli_query($con,$query);

				if(!empty($result_age) && mysqli_num_rows($result_age) > 0)
				{
					$row_age = mysqli_fetch_assoc($result_age);
					$age = $row_age['age'];
				}
				else
				{
					$age = 0;
				};

				$query = "SELECT DOB FROM patients WHERE patient_id='$patient_id'";
				$result_dob = mysqli_query($con,$query);

				if(!empty($result_dob) && mysqli_num_rows($result_dob) > 0)
				{
					$row_dob = mysqli_fetch_assoc($result_dob);
					$date_of_birth = $row_dob['DOB'];
				}
				else
				{
					$date_of_birth = date('Y-m-d');
				};

				array_push($Patient_Data, 
					$age,
					$_POST['patient_id'],
					$_POST['attend_id'],
					$date_of_birth
				);
				 echo json_encode($Patient_Data);
			}

			function update_patient_age()
			{
				global $con;
				$patient_id = $_POST['patient_id'];
				$attend_id = $_POST['attend_id'];
				$age = $_POST['age'];
				$dob = $_POST['dob'];
				$age = addslashes($age);
			    
			    $query = "UPDATE `attendance` SET `age`='$age' WHERE `patient_id`='$patient_id' AND 
				`attend_id`='$attend_id'";
			    mysqli_query($con, $query);
			    
			    $query = "UPDATE `patients` SET `age`='$age',`DOB`='$dob' WHERE `patient_id`='$patient_id'";
			    mysqli_query($con, $query);
			}

			function set_nhis_regional_code()
			{
				global $con;
				$scheme_code = $_POST['scheme_code'];
				$query = "SELECT * from scheme where scheme_code='$scheme_code'";
				$result = mysqli_query($con,$query);
				$regional_code=array();
				if (mysqli_num_rows($result) > 0) {
					while($row=mysqli_fetch_assoc($result))
					{
						array_push($regional_code, 
							$row['regional_code'],
							$row['scheme_name'],
							$row['scheme_id']
						);
					}
				} else {
					array_push($regional_code, 
							'N/A',
							'N/A',
							'N/A'
						);

				};
				 echo json_encode($regional_code);
			}

			function Display_Patient()
			{
				global $con;
				$patient_id = $_POST['patient_id'];
				$query = "SELECT * from patients WHERE patient_id='$patient_id'";
				$result = mysqli_query($con,$query);

