			function save_patient()
			{
				global $con;
				$patient_details = array();
				$number = $_POST['number'];
				$folderNo = $_POST['folderNo'];
			    $firstName = $_POST['firstName'];
			    $lastName = $_POST['lastName'];
			    $full_name = $_POST['firstName'].' '.$_POST['lastName'];
			    $DOB = $_POST['DOB'];
			    $age = $_POST['age'];
			    $gender = $_POST['gender'];
			    $marital = $_POST['marital_status'];
			    $address = $_POST['address'];
			    $city = $_POST['city'];
			    $country = $_POST['patient_country'];
			    $nationality = $_POST['patient_nationality'];
			    $telephone = $_POST['telephone'];
			    $email = $_POST['email'];
			    $relname = $_POST['relname'];
			    $rellocation = $_POST['rellocation'];
			    $reltelephone = $_POST['reltelephone'];
			    $ghanacard = $_POST['ghanacard'];
			    $nhismemberno = $_POST['nhismemberno'];
			    $sponsor = $_POST['scheme_id'];
			    if(isset($_SESSION['company_id'])){$company_id = $_SESSION['company_id'];}else{$company_id = 0;};
			    if(isset($_SESSION['user_id'])){$user_id = $_SESSION['user_id'];}else{$user_id = 0;};
			    date_default_timezone_set("Africa/Accra");
			    $datetime = date('Y/m/d H:i:s');
				$branch_id = $_SESSION['branch_id'];
			    
			    $query = "INSERT INTO patients (company_id,folderNo, firstName, lastName, DOB, gender, marital, 
				address, city, telephone, email, full_name,relname, rellocation, reltelephone, ghanacard, 
				created_by, created_datetime, number, branch_id, nhismemberno, country, nationality, scheme_id) 
			    VALUES ('$company_id','$folderNo','$firstName','$lastName','$DOB','$gender','$marital','$address',
				'$city','$telephone','$email','$full_name','$relname','$rellocation','$reltelephone','$ghanacard',
				'$user_id','$datetime','$number','$branch_id','$nhismemberno','$country','$nationality','$sponsor')";
			    $query_run = mysqli_query($con, $query);
				if ($query_run)
			    {
					$query_patient = "SELECT * FROM patients ORDER BY patient_id DESC";
			        $query_run_patient = mysqli_query($con, $query_patient);
					$row_patient = mysqli_fetch_assoc($query_run_patient);
					array_push($patient_details, $row_patient['patient_id'],$row_patient['firstName'],
					$row_patient['lastName'],'Patient Added Successfully');
			    }
			    else
			    {
					array_push($patient_details,'NA','NA','NA','Patient NOT Added');
			    };
				echo json_encode($patient_details);
			}

			function edit_patient()
			{
				global $con;
				$patient_id = $_POST['patient_id'];
				$query = "SELECT * from patients where patient_id='$patient_id'";
				$result = mysqli_query($con,$query);
				while($row=mysqli_fetch_assoc($result))
				{
					$Patient_Data=array();
					$scheme_id = $row['scheme_id'];
					$query_scheme = "SELECT * from scheme where scheme_id='$scheme_id'";
					$result_scheme = mysqli_query($con,$query_scheme);
					if (mysqli_num_rows($result_scheme) > 0) {
						$row_scheme=mysqli_fetch_assoc($result_scheme);
						$scheme_name = $row_scheme['scheme_name'];
					} else {
						$scheme_name = 'N/A';
					};
					array_push($Patient_Data, 
						$row['patient_id'],$row['folderNo'],$row['firstName'],$row['lastName'],$row['DOB'],$row['gender'],
						$row['marital'],$row['address'],$row['city'],$row['telephone'],$row['email'],$row['Allergies'],
						$row['MedicalHistory'],$row['FamilyHistory'],$row['BloodGroup'],$row['G6PD'],$row['geno_type'],
						$row['sickling'],$row['relname'],$row['rellocation'],$row['reltelephone'],$row['Schname'],
						$row['nhismemberno'],$row['nhisexpirydate'],$row['prtinsname'],$row['prtmemberno'],$row['prtexpirydate'],
						$row['ghanacard'],$row['sn_scheme_code'],$row['sn_member'],$row['sn_regional_code'],$row['serial_no'],
						$row['scheme_id'], $scheme_name, $row['country'], $row['nationality']
					);
				}
				 echo json_encode($Patient_Data);
			}

