		//EMPLOYEE
			function tax_employee()
			{
				global $con;
				$basic_salary = $_POST['basic_salary'];
				$ssf_contribution = $_POST['ssf_contribution'];
				//TAX
					$taxable_income = $basic_salary - $ssf_contribution;

					$query_tax = "SELECT * FROM payroll_tax_schedule ORDER BY date DESC";
					$query_run_tax = mysqli_query($con, $query_tax);
					if(!empty($query_run_tax) && mysqli_num_rows($query_run_tax) > 0)
					{
						$row_tax = mysqli_fetch_assoc($query_run_tax);
						if($taxable_income <= $row_tax['CCI_1'] && $taxable_income){$tax =$taxable_income * $row_tax['Rate_1'];};
						if($taxable_income <= $row_tax['CCI_2'] && $taxable_income > $row_tax['CCI_1']){$tax = (($taxable_income - $row_tax['CCI_1']) * $row_tax['Rate_2']) + $row_tax['CT_1'];};
						if($taxable_income <= $row_tax['CCI_3'] && $taxable_income > $row_tax['CCI_2']){$tax = (($taxable_income - $row_tax['CCI_2']) * $row_tax['Rate_3']) + $row_tax['CT_2'];};
						if($taxable_income <= $row_tax['CCI_4'] && $taxable_income > $row_tax['CCI_3']){$tax = (($taxable_income - $row_tax['CCI_3']) * $row_tax['Rate_4']) + $row_tax['CT_3'];};
						if($taxable_income <= $row_tax['CCI_5'] && $taxable_income > $row_tax['CCI_4']){$tax = (($taxable_income - $row_tax['CCI_4']) * $row_tax['Rate_5']) + $row_tax['CT_4'];};
						if($taxable_income <= $row_tax['CCI_6'] && $taxable_income > $row_tax['CCI_5']){$tax = (($taxable_income - $row_tax['CCI_5']) * $row_tax['Rate_6']) + $row_tax['CT_5'];};
						if($taxable_income > $row_tax['CCI_6']){$tax = (($taxable_income - $row_tax['CCI_6']) * $row_tax['Rate_7']) + $row_tax['CT_6'];};
					}
					else
					{
						$tax = 0;
					};
				echo $tax;
			}

			function employee_set_staff_id()
			{
				global $con;
				$branch_id = $_POST['branch_id'];
				$dept_id = $_POST['dept_id'];
				$employment_type = $_POST['employment_type'];
				$staff_id = '';

				$query_branch = "SELECT * FROM branch WHERE branch_id='$branch_id'";
				$result_branch = mysqli_query($con,$query_branch);
				if(!empty($result_branch) && mysqli_num_rows($result_branch) > 0)
				{
					$row_branch = mysqli_fetch_assoc($result_branch);
					$branch_code = '-'.substr($row_branch['branch_name'],0, 2);
				}
				else
				{
					$branch_code = '';
				};

				$query_dept = "SELECT * FROM department WHERE dept_id='$dept_id'";
				$result_dept = mysqli_query($con,$query_dept);
				if(!empty($result_dept) && mysqli_num_rows($result_dept) > 0)
				{
					$row_dept = mysqli_fetch_assoc($result_dept);
					$dept_code = '-'.$row_dept['code'];
				}
				else
				{
					$dept_code = '';
				};

				$query = "SELECT * FROM payroll_employee WHERE employment_type='$employment_type' ORDER BY sno DESC";
				$result = mysqli_query($con,$query);
				if(!empty($result) && mysqli_num_rows($result) > 0)
				{
					$row = mysqli_fetch_assoc($result);
					$bsno = $row['sno'] + 1;
				}
				else
				{
					$bsno = 1;
				};

				if($employment_type == 'NATIONAL SERVICE')
				{
					$bsno = 'NSS'.$bsno;
				}
				else if($employment_type == 'SUB-CONTRACTORS')
				{
					$bsno = 'SBC'.$bsno;
				};

				$staff_id = 'RSL'.$branch_code.''.$dept_code.'-'.$bsno;
				echo $staff_id;
			}

