				`total_allowance`,`total_deduction`,`gross_salary`) 
				VALUES ('$sno','$bsno','$company_id','$branch_id', '$first_name','$last_name','$position','$employee_branch_id',
				'$bank_account_number','$bank','$bank_branch','$ghanacard','$ssf_no','$basic_salary','$fuel_allowance',
