			function delete_employee()
			{
				global $con;
				$status = '';
				$employee_id = $_POST['employee_id'];
				$query = "SELECT * FROM payroll_pay_slip WHERE employee_id = '$employee_id'";
				$query_run = mysqli_query($con, $query);

				if (!empty($query_run) && mysqli_num_rows($query_run) > 0)
				{
					$status = 'used';
				}
				else
				{
					$query_delete = "DELETE FROM payroll_employee WHERE employee_id = '$employee_id'";
					mysqli_query($con, $query_delete);
					$status = 'deleted';
				};
	
				echo $status;
			}
			
