			function update_time_sheet()
			{
				global $con;
				$time_sheet_id = $_POST['time_sheet_id'];
				$time_sheet_branch_id = $_POST['time_sheet_branch_id'];
				$time_sheet_date = $_POST['time_sheet_date'];
				$authorized_by = $_POST['time_sheet_authorized_by'];
				$authorized_status = $_POST['time_sheet_authorized_status'];
				$authorized_by_hr = $_POST['time_sheet_authorized_by_hr'];
				$authorized_status_hr = $_POST['time_sheet_authorized_status_hr'];
				$approved_by = $_POST['time_sheet_approved_by'];
				$approved_status = $_POST['time_sheet_approved_status'];
				$company_id = $_SESSION['company_id'];
				$branch_id = $_SESSION['branch_id'];
				$user_id = $_SESSION['user_id'];
				
				if($company_id > 0)
				{
					$query = "UPDATE `payroll_time_sheet` SET `location`='$time_sheet_branch_id',
					`date`='$time_sheet_date', `altered_by`='$user_id', `altered_datetime`=NOW(),
					`authorized_by`='$authorized_by', `authorized_status`='$authorized_status', 
					`authorized_by_hr`='$authorized_by_hr', `authorized_status_hr`='$authorized_status_hr',
					`approved_by`='$approved_by',`approved_status`='$approved_status' 
					WHERE `time_sheet_id`='$time_sheet_id'";
					mysqli_query($con, $query);

					$query_del = "DELETE FROM payroll_time_sheet_list WHERE `time_sheet_id`='$time_sheet_id'";
					mysqli_query($con,$query_del);
					
					$number_as = count($_POST["time_sheet_employee_id"]);  
					if($number_as > 0)  
					{  
						for($i=0; $i < $number_as; $i++)  
						{  
							if(trim($_POST["time_sheet_employee_id"][$i] != ''))
							{ 
								$employee_id = $_POST['time_sheet_employee_id'][$i];
								$overtime_actual = $_POST['time_sheet_overtime_actual'][$i];
								$overtime = $_POST['time_sheet_overtime'][$i];
								$day67_actual = $_POST['time_sheet_day_6n7_actual'][$i];
								$day67 = $_POST['time_sheet_day_6n7'][$i];
								$holiday_actual = $_POST['time_sheet_holidays_actual'][$i];
								$holiday = $_POST['time_sheet_holidays'][$i];
								$absent = $_POST['time_sheet_absent'][$i];

								$query = "SELECT sno FROM payroll_time_sheet_list WHERE company_id = '$company_id' ORDER BY sno DESC";
								$result = mysqli_query($con,$query);
								$row = mysqli_fetch_assoc($result);
								if(isset($row)){$sno = $row['sno'] + 1;}else{$sno = 1;}
								
								$query = "INSERT INTO `payroll_time_sheet_list`(`sno`,`company_id`, `branch_id`,`time_sheet_id`,
								`employee_id`, `normal_overtime`, `day_67`, `holidays`, `normal_overtime_actual`, `day_67_actual`, 
								`holidays_actual`, `absent`, `created_by`, 
								`created_datetime`, `date`) VALUES ('$sno','$company_id','$branch_id','$time_sheet_id','$employee_id',
								'$overtime','$day67','$holiday','$overtime_actual','$day67_actual','$holiday_actual','$absent','$user_id',NOW(),'$time_sheet_date')";
								mysqli_query($con, $query);
							};
						};
					};
				};
			}

			function display_time_sheet()
			{
				global $con;
				$_SESSION['time_sheet_id'] = $_POST['time_sheet_id'];
				$_SESSION['ts_branch_id'] = $_POST['branch_id'];
				$_SESSION['ts_branch_name'] = $_POST['branch_name'];
				$_SESSION['ts_date'] = $_POST['date'];
			}

			function search_time_sheet_by_date()
			{
				global $con;
				$start_date = $_POST['start_date'];
				$end_date = $_POST['end_date'];
				$company_id = $_SESSION['company_id'];
				$branch_id = $_SESSION['branch_id'];
				$date_today = date('Y-m-d');
				$user_id = $_SESSION['user_id'];
				$value = "";

				$query_branch_count = "SELECT * FROM branch WHERE company_id = '$company_id'";
				$query_run_branch_count = mysqli_query($con, $query_branch_count);
				if (mysqli_num_rows($query_run_branch_count) > 1)
				{
					if ($_SESSION['user_type_id'] != 3) 
					{
						$query = "SELECT * FROM payroll_time_sheet WHERE company_id = '$company_id' 
						AND date BETWEEN '$start_date' AND '$end_date' ORDER BY date DESC, time_sheet_id ASC";
					}
					else
					{
						$query = "SELECT * FROM payroll_time_sheet WHERE company_id = '$company_id' 
						AND branch_id = '$branch_id' AND date BETWEEN '$start_date' AND '$end_date' ORDER BY date DESC, time_sheet_id ASC";
					};
				}
				else
				{
					$query = "SELECT * FROM payroll_time_sheet WHERE company_id = '$company_id' 
					AND date BETWEEN '$start_date' AND '$end_date' ORDER BY date DESC, time_sheet_id ASC";
				};
				$query_run = mysqli_query($con, $query);
					
				$value = '<table class="table table-hover table-bordered table-sm" id="time_sheetTable" width="100%" cellspacing="0">
					<thead>
						<tr>
							<th class="action-td">Date</th>
							<th class="action-td">Branch</th>
							<!--<th class="action-td">Department</th>-->
							<th class="action-td">No of Employees</th>
							<th class="action-td">Overtime</th>
							<th class="action-td">Day 6 and 7</th>
							<th class="action-td">Holidays</th>
							<th class="action-td">Action</th>
						</tr>
					</thead>
					<tbody class="pv-table-body">';
					if (mysqli_num_rows($query_run) > 0)
					{
						while($row = mysqli_fetch_assoc($query_run))
						{
							$branch_id = $row['location'];
							$query_branch = "SELECT * FROM branch WHERE branch_id = '$branch_id'";
							$query_run_branch = mysqli_query($con, $query_branch);
							if(!empty($query_run_branch) && mysqli_num_rows($query_run_branch) > 0)
							{
								$row_branch = mysqli_fetch_assoc($query_run_branch);
								$branch_name = $row_branch['branch_name'];
							}
							else
							{
								$branch_name = 'Not Specified';
							};

							$dept_id = $row['dept_id'];
							$query_dept = "SELECT * FROM department WHERE dept_id = '$dept_id'";
							$query_run_dept = mysqli_query($con, $query_dept);
							if(!empty($query_run_dept) && mysqli_num_rows($query_run_dept) > 0)
							{
								$row_dept = mysqli_fetch_assoc($query_run_dept);
