							{
								$row_ts = mysqli_fetch_assoc($query_run_ts);
								$overtime = $row_ts['overtime'];
								$day_67_overtime = $row_ts['day_67'];
								$holidays = $row_ts['holidays'];
							}
							else
							{
								$overtime = 0;
								$day_67_overtime = 0;
								$holidays = 0;
							};
							$query_ts = "SELECT * FROM payroll_time_sheet_list WHERE time_sheet_id = '$time_sheet_id'";
