							{
								$no_of_empoyees = 0;
							};
				
							if($row['authorized_status']=='Authorized' && $row['approved_status']=='Pending'){$value .= '<tr style="background-color:yellow; color:black">';}
							else if($row['authorized_status']=='Authorized' && $row['approved_status']=='Approved'){$value .= '<tr style="background-color:red; color:black">';}
							else if($row['authorized_status']=='Pending' && $row['approved_status']=='Pending'){$value .= '<tr>';}
							else if($row['authorized_status']=='Pending' && $row['approved_status']=='Approved'){$value .= '<tr style="background-color:orange; color:black">';}
								$value .='<td class="action-td">
									<a href="#" id="btn_edit_time_sheet" data-id="'.$row['time_sheet_id'].'">'.$row['date'].'</a>
								</td>
								<td>'.$branch_name.'</td>
