		//LOAN DISBURSEMENT
			function save_loan_disbursement()
			{
				global $con;
				$loan_disburse_id = $_POST['loan_disbursement_id'];
				$employee_id = $_POST['employee_id'];
				$trans_date = $_POST['date'];
				$effective_date = $_POST['effective_date'];
				$principal = $_POST['principal'];
				$duration = $_POST['duration'];
				$interest = $_POST['interest'];
				$interest_calc_type = $_POST['interest_calc_type'];
				$debit_ledger = $_POST['debit_ledger'];
				$credit_ledger = $_POST['credit_ledger'];
				$narration = 'Loan Disbursement '.$_POST['narration'];
				$principal_beginning = $_POST['principal'];
				$company_id = $_SESSION['company_id'];
				$branch_id = $_SESSION['branch_id'];
				$user_id = $_SESSION['user_id'];

				$query = "SELECT sno FROM payroll_loan_disburse WHERE company_id = '$company_id' ORDER BY sno DESC";
				$result = mysqli_query($con,$query);
				$row = mysqli_fetch_assoc($result);
				if(isset($row)){$sno = $row['sno'] + 1;}else{$sno = 1;};
				
				$query = "INSERT INTO `payroll_loan_disburse`(`sno`,`company_id`, `branch_id`,`date`,`effective_date`, 
				`employee_id`,`principal`, `interest_rate`, `duration`, `interest_type`, `debit_ledger`, `credit_ledger`,
				`narration`,`created_by`, `created_datetime`) 
				VALUES ('$sno','$company_id','$branch_id','$trans_date','$effective_date','$employee_id','$principal','$interest',
				'$duration','$interest_calc_type','$debit_ledger','$credit_ledger','$narration','$user_id',NOW())";
				$query_run = mysqli_query($con, $query);
				if($query_run)
				{
					$query_ld = "SELECT * FROM payroll_loan_disburse WHERE company_id = '$company_id' ORDER BY 
					loan_disburse_id DESC";
					$result_ld = mysqli_query($con, $query_ld);
					$row_ld = mysqli_fetch_assoc($result_ld);
					$loan_disburse_id = $row_ld['loan_disburse_id'];
					$_SESSION['loan_disburse_id'] = $row_ld['loan_disburse_id'];
					
					$query_delete = "DELETE FROM `payroll_loan_schedule` WHERE `loan_disburse_id`='$loan_disburse_id'";
					mysqli_query($con, $query_delete);
					
					if($interest_calc_type == 'Reducing Balance')
					{
						for ($x = 1; $x <= $duration; $x++) 
						{
							$effective_date = date('Y-m-d', strtotime('+1 month', strtotime($effective_date)));
							$repayment = $principal * ($interest + ($interest / ((pow((1 + $interest),$duration)) - 1 )));
							$interest_payment = $principal_beginning * $interest;
							$principal_payment = $repayment - $interest_payment;
							$principal_remaining = $principal_beginning - $principal_payment;

							$query = "INSERT INTO `payroll_loan_schedule`(`company_id`,`branch_id`,`user_id`,
							`loan_disburse_id`,`employee_id`,`date`,`principal_begining`,`repayment`,
							`extra_payment`,`total_payment`,`principal_payment`,`interest_payment`,`principal_remaining`,
							`created_by`,`created_datetime`) VALUES ('$company_id','$branch_id','$user_id','$loan_disburse_id',
							'$employee_id','$effective_date','$principal_beginning','$repayment',0,'$repayment','$principal_payment',
							'$interest_payment','$principal_remaining','$user_id',NOW())";
							$query_run = mysqli_query($con, $query);
							if($query_run)
							{
								$principal_beginning = $principal_remaining;
							};
						};
					}
					else
					{
						for ($x = 1; $x <= $duration; $x++) 
						{
							$effective_date = date('Y-m-d', strtotime('+1 month', strtotime($effective_date)));
							$repayment = ($principal + (($principal * $interest) * $duration))/$duration;
							$interest_payment = $principal * $interest;
							$principal_payment = $repayment - $interest_payment;
							$principal_remaining = $principal_beginning - $principal_payment;

							$query = "INSERT INTO `payroll_loan_schedule`(`company_id`,`branch_id`,`user_id`,
							`loan_disburse_id`,`employee_id`,`date`,`principal_begining`,`repayment`,
							`extra_payment`,`total_payment`,`principal_payment`,`interest_payment`,`principal_remaining`,
							`created_by`,`created_datetime`) VALUES ('$company_id','$branch_id','$user_id','$loan_disburse_id',
							'$employee_id','$effective_date','$principal_beginning','$repayment',0,'$repayment','$principal_payment',
							'$interest_payment','$principal_remaining','$user_id',NOW())";
							$query_run = mysqli_query($con, $query);
							if($query_run)
							{
								$principal_beginning = $principal_remaining;
							};
						};
					};
					
					$query_dr = "INSERT INTO `transactions`(
						`loan_disburse_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `date`, `amount`, 
						`amount_debit`, `amount_credit`, `narration`) VALUES (
						'$loan_disburse_id','$debit_ledger','$credit_ledger','$company_id','$user_id','$trans_date',
						'$principal','$principal',0,'$narration')";
						mysqli_query($con, $query_dr);

						$query_cr = "INSERT INTO `transactions`(
						`loan_disburse_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `date`, `amount`, 
						`amount_debit`, `amount_credit`, `narration`) VALUES (
						'$loan_disburse_id','$credit_ledger','$debit_ledger','$company_id','$user_id','$trans_date',
						'$principal',0,'$principal','$narration')";
						mysqli_query($con, $query_cr);
				};
			}

