			function save_pay_sheet()
			{
				global $con;
				$start = $_POST['start_date'];
				$end = $_POST['end_date'];
				$date_start = date("Y-m-01", strtotime($end));
				$year_start = date("Y-01-01", strtotime($date_start));
				$year_end = date("Y-12-t", strtotime($date_start));

				$company_id = $_SESSION['company_id'];
				$branch_id = $_SESSION['branch_id'];
				$user_id = $_SESSION['user_id'];

				$query_ps = "SELECT * FROM payroll_pay_sheet WHERE date BETWEEN '$start' AND '$end'";
				$result_ps = mysqli_query($con,$query_ps);
				
				if(!empty($result_ps) && mysqli_num_rows($result_ps) < 1)
				{
					$query_employee = "SELECT * FROM payroll_employee WHERE status = 'Active'";
					$result_employee = mysqli_query($con, $query_employee);
					if(!empty($result_employee) && mysqli_num_rows($result_employee) > 0)
					{
