						`date_to`,`created_by`, `created_datetime`) VALUES ('$sno','$company_id','$branch_id',
						'$end','$start','$end','$user_id',NOW())";
						$query_run = mysqli_query($con, $query);
						if($query_run)
						{
							$query_ld = "SELECT * FROM payroll_pay_sheet ORDER BY 
							pay_sheet_id DESC";
							$result_ld = mysqli_query($con, $query_ld);
							$row_ld = mysqli_fetch_assoc($result_ld);
							$pay_sheet_id = $row_ld['pay_sheet_id'];
							$_SESSION['pay_sheet_id'] = $row_ld['pay_sheet_id'];
							//SET TOTAL VARIABLES
								$total_basic_salary = 0;
								$total_fuel_allowance = 0;
								$total_clothing_allowance = 0;
								$total_other_allowance = 0;
								$total_normal_overtime = 0;
								$total_holiday = 0;
								$total_day_67 = 0;
								$total_bonus = 0;
								$total_paid_leave = 0;
								$total_salary_arrears = 0;
								$total_absentism = 0;
								$total_welfare = 0;
								$total_ssf_contribution = 0;
								$total_ssnit_arrears = 0;
								$total_ssf_employer = 0;
								$total_other_deductions = 0;
								$total_loan_repayment = 0;
								$total_tax = 0;
								$total_salary_advance = 0;
								$total_emolument = 0;
								$total_net_salary = 0;
								while($row_employee = mysqli_fetch_assoc($result_employee))
								{
									$employee_id = $row_employee['employee_id'];
									$basic_salary = $row_employee['basic_salary'];

									$query_payslip_exist = "SELECT * FROM payroll_pay_slip WHERE date BETWEEN '$start' AND '$end' AND employee_id='$employee_id'";
									$result_payslip_exist = mysqli_query($con, $query_payslip_exist);
									if(!empty($result_payslip_exist) && mysqli_num_rows($result_payslip_exist) < 1)
									{
										//ZERO VARIABLES
											$branch_id = 0;
											$dept_id = 0;
											$account_number = 0;
											$bank = 0;
											$bank_code = 0;
											$bank_branch = 0;
											$bank_branch_code = 0;
											$fuel_allowance = 0;
											$clothing_allowance = 0;
											$other_allowance = 0;
											$hourly_rate = 0;
											$daily_rate = 0;
											$overtime_rate = 0;
											$holiday_rate = 0;
											$day_67_rate = 0;
											$salary_arrears = 0;
											$welfare = 0;
											$other_deductions = 0;
											$ssf_employer = 0;
											$ssf_1st_tier = 0;
											$ssf_2nd_tier = 0;
											$ssf_contribution = 0;
											$position = 0;
											$location = 0;
											$ssnit_number = 0;

										//SALARY ADJUSTMENT
											$query_tsa = "SELECT SUM(current_adjustment) AS total_salary_adjustment FROM salary_adjustment_list 
											WHERE employee_id = '$employee_id' AND date <= '$end' GROUP BY employee_id LIMIT 1";
											$query_run_tsa = mysqli_query($con, $query_tsa);
											if(!empty($query_run_tsa) && mysqli_num_rows($query_run_tsa) > 0)
											{
												$row_tsa = mysqli_fetch_assoc($query_run_tsa);
												$total_salary_adjustment = $row_tsa['total_salary_adjustment'];
											}
											else
											{
												$total_salary_adjustment = 0;
											};

										//SALARY ARREARS
											$query_arrears = "SELECT SUM(salary_arrears) AS salary_arrears FROM arrears 
											WHERE employee_id = '$employee_id' AND date BETWEEN '$start' AND '$end' GROUP BY employee_id  LIMIT 1";
											$query_run_arrears = mysqli_query($con, $query_arrears);
											if(!empty($query_run_arrears) && mysqli_num_rows($query_run_arrears) > 0)
											{
												$row_arrears = mysqli_fetch_assoc($query_run_arrears);
												$salary_arrears = $row_arrears['salary_arrears'];
											}
											else
											{
												$salary_arrears = 0;
											};

										//SSNIT ARREARS
											$query_ssnit = "SELECT SUM(tier_1_arrears) AS tier_1_arrears, SUM(tier_2_arrears) AS 
											tier_2_arrears, SUM(ssf_employee_arrears) AS ssf_employee_arrears, SUM(ssf_employer_arrears) AS 
											ssf_employer_arrears, ssnit_arrears_type FROM arrears WHERE employee_id = '$employee_id' AND date 
											BETWEEN '$start' AND '$end' GROUP BY employee_id  LIMIT 1";
											$query_run_ssnit = mysqli_query($con, $query_ssnit);
											if(!empty($query_run_ssnit) && mysqli_num_rows($query_run_ssnit) > 0)
											{
												$row_ssnit = mysqli_fetch_assoc($query_run_ssnit);
												$tier_1_arrears = $row_ssnit['tier_1_arrears'];
												$tier_2_arrears = $row_ssnit['tier_2_arrears'];
												$ssf_employee_arrears = $row_ssnit['ssf_employee_arrears'];
												$ssf_employer_arrears = $row_ssnit['ssf_employer_arrears'];
												$ssnit_arrears_type = $row_ssnit['ssnit_arrears_type'];
											}
											else
											{
												$tier_1_arrears = 0;
												$tier_2_arrears = 0;
												$ssf_employee_arrears = 0;
												$ssf_employer_arrears = 0;
												$ssnit_arrears_type = 0;
											};

										//BONUS
											$query_bonus = "SELECT SUM(bonus_amount) AS bonus_amount FROM bonus_list 
											WHERE employee_id = '$employee_id' AND date BETWEEN '$start' AND '$end' 
											GROUP BY employee_id  LIMIT 1";
											$query_run_bonus = mysqli_query($con, $query_bonus);
											if(!empty($query_run_bonus) && mysqli_num_rows($query_run_bonus) > 0)
											{
												$row_bonus = mysqli_fetch_assoc($query_run_bonus);
												$bonus = $row_bonus['bonus_amount'];
											}
											else
											{
												$bonus = 0;
											};

										//BONUS_TAX
											if($bonus > 0)
											{
												$begining_of_year = date("Y-01-01");
												$end_of_year = date("Y-12-31");

												//TOTAL_BONUS
													$query_bon = "SELECT SUM(bonus_amount) AS total_bonus FROM bonus_list 
													WHERE employee_id = '$employee_id' AND date BETWEEN '$begining_of_year' AND '$end_of_year' 
													GROUP BY employee_id  LIMIT 1";
													$query_run_bon = mysqli_query($con, $query_bon);
													if(!empty($query_run_bon) && mysqli_num_rows($query_run_bon) > 0)
													{
														$row_bon = mysqli_fetch_assoc($query_run_bon);
														$total_bonus = $row_bon['total_bonus'];
													}
													else
													{
														$total_bonus = 0;
													};

												//ANNUAL_SALARY
													$annual_salary = 0;
													for ($i = 1; $i <= 12; $i++) 
													{
														if($i < 10){$m='0'.$i;}else{$m=$i;};
														$end_of_month = date('Y-'.$m.'-t');

														$query_sa = "SELECT SUM(current_adjustment) AS salary_adjustment FROM salary_adjustment_list 
														WHERE employee_id = '$employee_id' AND date <= '$end_of_month' GROUP BY employee_id LIMIT 1";
														$query_run_sa = mysqli_query($con, $query_sa);
														if(!empty($query_run_sa) && mysqli_num_rows($query_run_sa) > 0)
														{
															$row_sa = mysqli_fetch_assoc($query_run_sa);
															$salary_adjustment = $row_sa['salary_adjustment'];
														}
														else
														{
															$salary_adjustment = 0;
														};
														$annual_salary = $annual_salary + $basic_salary + $salary_adjustment;
													}

												//BONUS
													$bonus_threshold = $annual_salary * 0.15;
													if($total_bonus <= $bonus_threshold)
													{
														$bonus_tax = 0.05 * $bonus;
													}
													else
													{
														$previous_bonus = $total_bonus - $bonus;
														if(($bonus_threshold - $previous_bonus) > 0)
														{
															$bonus_tax = ($bonus_threshold - $previous_bonus) * 0.05;
															$taxable_bonus = $bonus - ($bonus_threshold - $previous_bonus);
														}
														else
														{
															$bonus_tax = 0.05 * $bonus_threshold;
															$taxable_bonus = $bonus - $bonus_threshold;
														};
													};
											}
											else
											{
												$bonus_tax = 0;
												$taxable_bonus = 0;
											};
									
									
											$current_basic_salary = $basic_salary + $total_salary_adjustment;
											$daily_rate = round(($current_basic_salary/27),2);
											$hourly_rate = round(($daily_rate/8),2);
											
											if($row_employee['ssf_remarks'] == 'Yes')
											{
												$ssf_contribution = round(($current_basic_salary * 0.055),2);
												$ssf_employer = round(($current_basic_salary * 0.13),2);
												$ssf_2nd_tier = round(($current_basic_salary * 0.05),2);
												$ssf_1st_tier = round(($current_basic_salary * 0.135),2);
											}
											else
											{
												$ssf_contribution = 0;
												$ssf_employer = 0;
												$ssf_2nd_tier = 0;
												$ssf_1st_tier = 0;
											};

											$holiday_rate = round(($hourly_rate * 2),2);
											$day_67_rate = round(($hourly_rate * 2),2);
											$overtime_rate = round(($hourly_rate * 1.5),2);
											$pf_employer = 0;
											$pf_employee = 0;

											$fuel_allowance = $row_employee['fuel_allowance'];
											$clothing_allowance = $row_employee['clothing_allowance'];
											$other_allowance = $row_employee['other_allowance'];
											$branch_id = $row_employee['branch_id'];
											$other_deductions = $row_employee['other_deductions'];
											$account_number = $row_employee['account_number'];
											$bank = $row_employee['bank'];
											$bank_code = $row_employee['bank_code'];
											$bank_branch = $row_employee['bank_branch'];
											$bank_branch_code = $row_employee['bank_branch_code'];
											$welfare = $row_employee['welfare'];
											$date_join = $row_employee['date_join'];
											$date_exit = $row_employee['date_exit'];
											$position = $row_employee['position'];
											$location = $row_employee['location'];
											$ssnit_number = $row_employee['ssnit_number'];
											$staff_id = $row_employee['staff_id'];
											$tax_remarks = $row_employee['tax_remarks'];
											$actual_basic_salary = $current_basic_salary;

											//PAID_LEAVE
												$query_leave = "SELECT leave_annual AS paid_leave_days FROM payroll_leave 
												WHERE employee_id = '$employee_id' AND leave_outcome ='Paid' LIMIT 1";
												$query_run_leave = mysqli_query($con, $query_leave);
												if(!empty($query_run_leave) && mysqli_num_rows($query_run_leave) > 0)
												{
													$row_leave = mysqli_fetch_assoc($query_run_leave);
													$paid_leave_days = $row_leave['paid_leave_days'];
												}
												else
												{
													$paid_leave_days = 0;
												};

												$paid_leave_amount = round(($paid_leave_days * $daily_rate),2);
												//POST PAY DATA
													$extra_ssf_contribution = $ssf_contribution - $actual_ssf_contribution;
													

												//OVERTIME
													$query_ts = "SELECT SUM(tsl.normal_overtime) AS overtime, SUM(tsl.day_67) AS day_67, 
													SUM(tsl.holidays) AS holidays, SUM(tsl.absent) AS absent_days, ts.date, tsl.employee_id 
													FROM payroll_time_sheet_list tsl JOIN payroll_time_sheet ts ON tsl.time_sheet_id = ts.time_sheet_id 
													WHERE ts.approved_status = 'Approved' AND tsl.employee_id = '$employee_id' AND ts.date BETWEEN '$start' AND '$end'";
													$query_run_ts = mysqli_query($con, $query_ts);
													if(!empty($query_run_ts) && mysqli_num_rows($query_run_ts) > 0)
													{
														$row_ts = mysqli_fetch_assoc($query_run_ts);
														if($row_ts['overtime'] != NULL){$overtime = $row_ts['overtime'];}else{$overtime = 0;};
														if($row_ts['day_67'] != NULL){$day_67_hrs = $row_ts['day_67'];}else{$day_67_hrs = 0;};
														if($row_ts['holidays'] != NULL){$holidays_hrs = $row_ts['holidays'];}else{$holidays_hrs = 0;};
														if($row_ts['absent_days'] != NULL){$absent_days = $row_ts['absent_days'];}else{$absent_days = 0;};

														$normal_overtime = $overtime_rate * $overtime;
														$holiday = $holiday_rate * $holidays_hrs;
														$day_67 = $day_67_rate * $day_67_hrs;
														$absentism = $daily_rate * $absent_days;
													}
													else
													{
														$normal_overtime = 0;
														$holiday = 0;
														$day_67 = 0;
														$absentism = 0;
													};
												
												//LOAN
													$query_loan = "SELECT SUM(repayment) AS repayment  FROM payroll_loan_schedule WHERE 
													employee_id = '$employee_id' AND date BETWEEN '$start' AND '$end'";
													$query_run_loan = mysqli_query($con, $query_loan);
													if(!empty($query_run_loan) && mysqli_num_rows($query_run_loan) > 0)
													{
														$row_loan = mysqli_fetch_assoc($query_run_loan);
														if($row_loan['repayment'] != NULL){$loan_repayment = $row_loan['repayment'];}else{$loan_repayment = 0;};
													}
													else
													{
														$loan_repayment = 0;
													};
												
												//SALARY ADVANCE
													$query_sa = "SELECT SUM(amount) AS salary_advance  FROM payroll_salary_advance WHERE 
													employee_id = '$employee_id' AND date BETWEEN '$start' AND '$end'";
													$query_run_sa = mysqli_query($con, $query_sa);
													if(!empty($query_run_sa) && mysqli_num_rows($query_run_sa) > 0)
													{
														$row_sa = mysqli_fetch_assoc($query_run_sa);
														if($row_sa['salary_advance'] != NULL){$salary_advance = $row_sa['salary_advance'];}else{$salary_advance = 0;};
													}
													else
													{
														$salary_advance = 0;
													};

												//TAX
													//$taxable_income = $actual_basic_salary - ($ssf_contribution + $extra_ssf_contribution);
													$taxable_income = $current_basic_salary - $ssf_contribution;
													if($tax_remarks == 'Yes')
													{
														$query_tax = "SELECT * FROM payroll_tax_schedule ORDER BY date DESC";
														$query_run_tax = mysqli_query($con, $query_tax);
														if(!empty($query_run_tax) && mysqli_num_rows($query_run_tax) > 0)
														{
															$row_tax = mysqli_fetch_assoc($query_run_tax);
															if($taxable_income <= $row_tax['CCI_1'] && $taxable_income){$tax =$taxable_income * $row_tax['Rate_1'];};
															if($taxable_income <= $row_tax['CCI_2'] && $taxable_income > $row_tax['CCI_1']){$tax = (($taxable_income - $row_tax['CCI_1']) * $row_tax['Rate_2']) + $row_tax['CT_1'];};
															if($taxable_income <= $row_tax['CCI_3'] && $taxable_income > $row_tax['CCI_2']){$tax = (($taxable_income - $row_tax['CCI_2']) * $row_tax['Rate_3']) + $row_tax['CT_2'];};
															if($taxable_income <= $row_tax['CCI_4'] && $taxable_income > $row_tax['CCI_3']){$tax = (($taxable_income - $row_tax['CCI_3']) * $row_tax['Rate_4']) + $row_tax['CT_3'];};
															if($taxable_income <= $row_tax['CCI_5'] && $taxable_income > $row_tax['CCI_4']){$tax = (($taxable_income - $row_tax['CCI_4']) * $row_tax['Rate_5']) + $row_tax['CT_4'];};
															if($taxable_income <= $row_tax['CCI_6'] && $taxable_income > $row_tax['CCI_5']){$tax = (($taxable_income - $row_tax['CCI_5']) * $row_tax['Rate_6']) + $row_tax['CT_5'];};
															if($taxable_income > $row_tax['CCI_6']){$tax = (($taxable_income - $row_tax['CCI_6']) * $row_tax['Rate_7']) + $row_tax['CT_6'];};
														}
														else
														{
															$tax = 0;
														};

														$tax = $tax + $bonus_tax;
													}
													else
													{
														$tax = 0;
													};

												//GET TOTALS
													$total_basic_salary = $total_basic_salary + $actual_basic_salary ;
													$total_fuel_allowance = $total_fuel_allowance + $fuel_allowance;
													$total_clothing_allowance = $total_clothing_allowance + $clothing_allowance;
													$total_other_allowance = $total_other_allowance + $other_allowance;
													$total_normal_overtime = $total_normal_overtime + $normal_overtime;
													$total_holiday = $total_holiday + $holiday;
													$total_day_67 = $total_day_67 + $day_67;
													$total_bonus = $total_bonus + $bonus;
													$total_paid_leave = $total_paid_leave + $paid_leave_amount;
													$total_absentism = $total_absentism + $absentism;
													$total_welfare = $total_welfare + $welfare;
