													$total_loan_repayment = $total_loan_repayment + $loan_repayment;
													$total_tax = $total_tax + $tax;
													$total_ssf_employer = $total_ssf_employer + $ssf_employer;
													$total_other_deductions = $total_other_deductions + $other_deductions;
													$total_salary_advance = $total_salary_advance + $salary_advance;

												//INSERT DATA
													$query_ps = "INSERT INTO `payroll_pay_slip`(`sno`,`company_id`, `branch_id`,`pay_sheet_id`,`employee_id`, 
													`date`,`position`,`location`, `account_number`,`bank`,`bank_code`,`ssnit_number`,`basic_salary`,
													`fuel_allowance`, `clothing_allowance`,`other_allowance`,`hourly_rate`,`daily_rate`,`overtime_rate`,
													`normal_overtime`, `holiday_rate`,`holiday`,`day_67_rate`,`day_67`,`welfare`,
													`other_deductions`, `ssf_rate`,`ssf_amount`,`ssf_employer`,`loan_repayment`,`tax`,
													`salary_advance`,`ssf_1st_tier`,`ssf_2nd_tier`,`created_by`, `created_datetime`, `absent`,
													`bank_branch`, `bank_branch_code`,  `bonus`, `paid_leave`,
													`salary_arrears`, `tier_1_arrears`, `tier_2_arrears`, `ssf_employee_arrears`, `ssf_employer_arrears`, `ssnit_arrears_type`) 
													VALUES ('$sno','$company_id','$branch_id','$pay_sheet_id','$employee_id','$end',
													'$position','$location','$account_number','$bank','$bank_code','$ssnit_number',
													'$actual_basic_salary','$fuel_allowance','$clothing_allowance','$other_allowance','$hourly_rate','$daily_rate',
													'$overtime_rate','$normal_overtime','$holiday_rate','$holiday','$day_67_rate','$day_67',
													'$welfare','$other_deductions','$ssf_contribution','$ssf_contribution','$ssf_employer',
													'$loan_repayment','$tax','$salary_advance','$ssf_1st_tier','$ssf_2nd_tier','$user_id',NOW(),'$absentism',
													'$bank_branch','$bank_branch_code','$bonus','$paid_leave_amount',
													'$salary_arrears','$tier_1_arrears','$tier_2_arrears','$ssf_employee_arrears','$ssf_employer_arrears','$ssnit_arrears_type')";
													mysqli_query($con,$query_ps);
													echo 'created';
											};
									};
								};
							

							//UPDATE TIME SHEET
								$query_ts_up = "UPDATE payroll_time_sheet SET pay_sheet_id = '$pay_sheet_id'
								WHERE approved_status = 'Approved' AND date BETWEEN '$start' AND '$end'";
								mysqli_query($con, $query_ts_up);

							$total_emolument = $total_basic_salary + $total_fuel_allowance + $total_clothing_allowance +
							$total_other_allowance + $total_normal_overtime + $total_holiday + $total_day_67 +
							$total_bonus + $total_paid_leave + $total_salary_arrears;
							
							$total_net_salary = $total_emolument - $total_welfare - $total_ssf_contribution -
							$total_loan_repayment - $total_tax - $total_salary_advance - $total_absentism - $total_other_deductions;
							//POSTING
								if($total_net_salary > 0)
								{
									$narration = 'Total Net Salary for '.$end;
									$query_dr = "INSERT INTO `transactions`(
									`pay_sheet_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `date`, `amount`, 
									`amount_debit`, `amount_credit`, `narration`) VALUES (
									'$pay_sheet_id',51,44,'$company_id','$user_id','$end',
									'$total_net_salary','$total_net_salary',0,'$narration')";
									mysqli_query($con, $query_dr);
					
									$query_cr = "INSERT INTO `transactions`(
									`pay_sheet_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `date`, `amount`, 
									`amount_debit`, `amount_credit`, `narration`) VALUES (
