									mysqli_query($con, $query_cr);
								};
								
								if($total_welfare > 0)
								{
									$narration = 'Total PF Deduction for '.$end;
									$query_dr = "INSERT INTO `transactions`(
									`pay_sheet_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `date`, `amount`, 
									`amount_debit`, `amount_credit`, `narration`) VALUES (
									'$pay_sheet_id',51,47,'$company_id','$user_id','$end',
									'$total_pf_employee','$total_pf_employee',0,'$narration')";
									mysqli_query($con, $query_dr);
					
									$query_cr = "INSERT INTO `transactions`(
									`pay_sheet_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `date`, `amount`, 
									`amount_debit`, `amount_credit`, `narration`) VALUES (
									'$pay_sheet_id',47,51,'$company_id','$user_id','$end',
									'$total_pf_employee',0,'$total_pf_employee','$narration')";
									mysqli_query($con, $query_cr);
								};
								
								if($total_other_deductions > 0)
								{
									$narration = 'Total PF Employer for '.$end;
									$query_dr = "INSERT INTO `transactions`(
									`pay_sheet_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `date`, `amount`, 
									`amount_debit`, `amount_credit`, `narration`) VALUES (
									'$pay_sheet_id',48,47,'$company_id','$user_id','$end',
									'$total_pf_employer','$total_pf_employer',0,'$narration')";
									mysqli_query($con, $query_dr);
					
									$query_cr = "INSERT INTO `transactions`(
									`pay_sheet_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `date`, `amount`, 
									`amount_debit`, `amount_credit`, `narration`) VALUES (
									'$pay_sheet_id',47,48,'$company_id','$user_id','$end',
									'$total_pf_employer',0,'$total_pf_employer','$narration')";
									mysqli_query($con, $query_cr);
								};
								
