			function edit_salary_adjustment()
			{
				global $con;
				$salary_adjustment_id = $_POST['salary_adjustment_id'];
				$salary_adjustment_details=array();
				$query = "SELECT * FROM payroll_salary_adjustment WHERE salary_adjustment_id='$salary_adjustment_id'";
				$result = mysqli_query($con,$query);
				while($row = mysqli_fetch_assoc($result))
				{
					array_push($salary_adjustment_details, 
						$row['salary_adjustment_id'],$row['employee_id'],$row['date'],$row['salary_adjustment_annual'],
						$row['salary_adjustment_sick'],$row['salary_adjustment_maternity'],$row['narration'],$row['authorised_by'],
						$row['approved_by'],$row['date_start'],$row['date_end'],$row['requested_annual'],
						$row['requested_sick'],$row['requested_maternity'],$row['authorised_comment'],
						$row['approved_comment']
					);
				}
				echo json_encode($salary_adjustment_details);
			}

			function update_salary_adjustment()
			{
				global $con;
				$salary_adjustment_id = $_POST['salary_adjustment_id'];
				$company_id = $_SESSION['company_id'];
				$branch_id = $_SESSION['branch_id'];
				$user_id = $_SESSION['user_id'];
				$salary_adjustment_employee = $_POST['salary_adjustment_employee'];
				$salary_adjustment_authorised_by = $_POST['salary_adjustment_authorised_by'];
				$salary_adjustment_approved_by = $_POST['salary_adjustment_approved_by'];
				$salary_adjustment_date = $_POST['salary_adjustment_date'];
				$start_date = $_POST['start_date'];
				$end_date = $_POST['end_date'];
				$requested_annual = $_POST['requested_annual'];
				$salary_adjustment_annual = $_POST['salary_adjustment_annual'];
				$requested_sick = $_POST['requested_sick'];
				$salary_adjustment_sick = $_POST['salary_adjustment_sick'];
				$requested_maternity = $_POST['requested_maternity'];
				$salary_adjustment_maternity = $_POST['salary_adjustment_maternity'];
				$salary_adjustment_narration = addslashes($_POST['salary_adjustment_narration']);
				$authorised_comment = addslashes($_POST['authorised_comment']);
				$approved_comment = addslashes($_POST['approved_comment']);

				$query = "UPDATE `payroll_salary_adjustment` SET `employee_id`='$salary_adjustment_employee', `authorised_by`='$salary_adjustment_authorised_by', 
				`approved_by`='$salary_adjustment_approved_by', `date`='$salary_adjustment_date', `date_start`='$start_date', 
				`date_end`='$end_date',`salary_adjustment_annual`='$salary_adjustment_annual',`requested_annual`='$requested_annual', 
				`salary_adjustment_sick`='$salary_adjustment_sick', `requested_sick`='$requested_sick', `salary_adjustment_maternity`='$salary_adjustment_maternity',
				`requested_maternity`='$requested_maternity', `narration`='$salary_adjustment_narration', 
				`authorised_comment`='$authorised_comment', `approved_comment`='$approved_comment',
				`altered_by`='$user_id', `altered_datetime`=NOW() WHERE `salary_adjustment_id`='$salary_adjustment_id'";
				mysqli_query($con, $query);
			}

