		//BONUS
			function bonus_voucher_save()
			{
				global $con;
				$company_id = $_SESSION['company_id'];
				$branch_id = $_SESSION['branch_id'];
				$user_id = $_SESSION['user_id'];
				$date = $_POST['bonus_voucher_date'];
				$location = $_POST['bonus_voucher_branch'];
				$calculation_type = $_POST['bonus_voucher_calculation_type'];
				$narration = $_POST['bonus_voucher_narration'];
				$amount = $_POST['bonus_voucher_amount'];

				$query = "INSERT INTO `bonus`(
				`company_id`, `branch_id`, `date`, `location`, `calculation_type`, `amount`, `narration`, 
				`created_by`, `created_datetime`) VALUES ('$company_id','$branch_id','$date','$location',
				'$calculation_type','$amount','$narration','$user_id',NOW())";
				
				$query_run = mysqli_query($con, $query);
				if ($query_run)
				{
					$query_bo = "SELECT * FROM bonus WHERE `company_id`='$company_id' ORDER BY bonus_id DESC LIMIT 1";
					$result_bo = mysqli_query($con,$query_bo);
					$row_bo = mysqli_fetch_assoc($result_bo);
					$bonus_id = $row_bo['bonus_id'];

					if($location != 'ALL' && $location > 0)
					{
						$query = "SELECT * FROM payroll_employee WHERE location='$location' AND status='Active' 
						AND (employment_type='REGULAR' OR employment_type ='REGULAR_PENSIONER')";
						$result = mysqli_query($con,$query);
						while($row = mysqli_fetch_assoc($result))
						{
							$basic_salary = $row['basic_salary'];
							$employee_id = $row['employee_id'];

							$query_sa = "SELECT SUM(current_adjustment) AS salary_adjustment FROM salary_adjustment_list 
							WHERE employee_id='$employee_id' AND date <= '$date'";
							$result_sa = mysqli_query($con,$query_sa);
							if(!empty($result_sa) && mysqli_num_rows($result_sa)> 0)
							{
								$row_sa = mysqli_fetch_assoc($result_sa);
								$salary_adjustment = $row_sa['salary_adjustment'];
							}
							else
							{
								$salary_adjustment = 0;
							};
							$total_salary = $basic_salary + $salary_adjustment;

							if($calculation_type == 'Percentage_Of_Salary')
							{
								$bonus = round($total_salary * $amount, 2);
							}
							else if($calculation_type == 'Flat_Amount')
							{
								$bonus = $amount;
							}
							$query_up = "INSERT INTO `bonus_list`(
							`company_id`, `branch_id`, `bonus_id`, `employee_id`, `location`, `date`, `calculation_type`, 
							`amount`, `basic_salary`, `bonus_amount`, `created_by`, `created_datetime`) VALUES ('$company_id',
							'$branch_id','$bonus_id','$employee_id', '$location','$date','$calculation_type','$amount',
							'$total_salary','$bonus','$user_id',NOW())";
							mysqli_query($con, $query_up);
						};
					}
					else
					{
						$query = "SELECT * FROM payroll_employee WHERE status='Active' 
						AND (employment_type='REGULAR' OR employment_type ='REGULAR_PENSIONER')";
						$result = mysqli_query($con,$query);
						while($row = mysqli_fetch_assoc($result))
						{
							$basic_salary = $row['basic_salary'];
							$employee_id = $row['employee_id'];

							$query_sa = "SELECT SUM(current_adjustment) AS salary_adjustment FROM salary_adjustment_list 
							WHERE employee_id='$employee_id' AND date <= '$date'";
							$result_sa = mysqli_query($con,$query_sa);
							if(!empty($result_sa) && mysqli_num_rows($result_sa)> 0)
							{
								$row_sa = mysqli_fetch_assoc($result_sa);
								$salary_adjustment = $row_sa['salary_adjustment'];
							}
							else
							{
								$salary_adjustment = 0;
							};
							$total_salary = $basic_salary + $salary_adjustment;

							if($calculation_type == 'Percentage_Of_Salary')
							{
								$bonus = round($total_salary * $amount, 2);

							}
							else if($calculation_type == 'Flat_Amount')
							{
								$bonus = $amount;
							}
							$query_up = "INSERT INTO `bonus_list`(
							`company_id`, `branch_id`, `bonus_id`, `employee_id`, `location`, `date`, `calculation_type`, 
							`amount`, `basic_salary`, `bonus_amount`, `created_by`, `created_datetime`) VALUES ('$company_id',
							'$branch_id','$bonus_id','$employee_id', '$location','$date','$calculation_type','$amount',
							'$total_salary','$bonus','$user_id',NOW())";
							mysqli_query($con, $query_up);
						};
					};
				};
			}
			
