						$serial_no = 'N/A';
						$ghana_card = 'N/A';
						$expiry_date = 'N/A';
					}
					else
					{
						$sql_pt = "SELECT * FROM payment_type WHERE patient_id = '$patient_id' AND ledger_id = 2 
						ORDER BY date_admit DESC"; 
