						$query = "SELECT A.*, P.firstName, P.lastName, P.telephone, P.folderNo, P.full_name FROM `patients` 
						AS P JOIN `attendance` AS A ON A.patient_id = P.patient_id WHERE 
						(P.firstName LIKE '%".$name."%' AND tos_id=1 AND date_admit='$date_today' AND (A.branch_id='$branch_id' OR A.share_status='SHARED'))
						OR (P.lastName LIKE '%".$name."%' AND tos_id=1 AND date_admit='$date_today' AND (A.branch_id='$branch_id' OR A.share_status='SHARED'))
						OR (P.telephone LIKE '%".$name."%' AND tos_id=1 AND date_admit='$date_today' AND (A.branch_id='$branch_id' OR A.share_status='SHARED'))
