			function search_attend_revenue_by_name()
			{
				global $con;
				$output = '';
				$search = mysqli_real_escape_string($con, $_POST["search"]);
				$criteria = mysqli_real_escape_string($con, $_POST["criteria"]);
				
				if($search !='' && $criteria == 'Name')
				{
					$query = "SELECT A.*, P.firstName, P.lastName, P.telephone, P.folderNo FROM `patients` 
					AS P JOIN `attendance` AS A ON A.patient_id = P.patient_id WHERE A.tos_id =2 AND A.outcome='discharged' AND P.firstName LIKE '%".$search."%'
					OR P.lastName LIKE '%".$search."%' ORDER BY A.date_admit DESC LIMIT 50";
				}
				else if($search !='' && $criteria == 'Telephone')
				{
					$query = "SELECT A.*, P.firstName, P.lastName, P.telephone, P.folderNo FROM `patients` 
					AS P JOIN `attendance` AS A ON A.patient_id = P.patient_id WHERE A.tos_id =2 AND A.outcome='discharged' 
					AND P.telephone LIKE '%".$search."%' ORDER BY A.date_admit DESC LIMIT 50";
				}
				else if($search !='' && $criteria == 'Folder_No')
				{
					$query = "SELECT A.*, P.firstName, P.lastName, P.telephone, P.folderNo FROM `patients` 
					AS P JOIN `attendance` AS A ON A.patient_id = P.patient_id WHERE A.tos_id =2 AND A.outcome='discharged' 
					AND P.folderNo LIKE '%".$search."%' ORDER BY A.date_admit DESC LIMIT 50";
				}
				else if($search !='' && $criteria == 'Membership_No')
				{
					$query = "SELECT A.*, P.firstName, P.lastName, P.telephone, P.folderNo FROM `patients` 
					AS P JOIN `attendance` AS A ON A.patient_id = P.patient_id WHERE A.tos_id =2 AND A.outcome='discharged' 
					AND P.nhismemberno LIKE '%".$search."%' ORDER BY A.date_admit DESC LIMIT 50";
				}
				else
				{
					$query = "SELECT A.*, P.firstName, P.lastName, P.telephone, P.folderNo FROM `patients` 
					AS P JOIN `attendance` AS A ON A.patient_id = P.patient_id WHERE A.tos_id =2 AND A.outcome='discharged'
					ORDER BY A.date_admit DESC LIMIT 50";
				};
				$query_run = mysqli_query($con, $query);
				$output .= '
