									if($row['nhis_led_id'] > 0 && $row['prvt_led_id'] > 0 )
									{
										$sponsor_id = $row['nhis_led_id'];
									}
                                    else if($row['nhis_led_id'] > 0 && $row['prvt_led_id'] <= 0 )
									{
										$sponsor_id = $row['nhis_led_id'];
									}
                                    else if($row['nhis_led_id'] <= 0 && $row['prvt_led_id'] > 0 )
									{
