		    function history_medical_img_upload()
		    {
		    	global $con;
		    	if (isset($_POST['hx_med_list_img_save_btn'])) 
				{
					$company_id = $_SESSION['company_id'];
					$branch_id = $_SESSION['branch_id'];
					$user_id = $_SESSION['user_id'];
		    		$attend_id = $_POST['attend_id_img'];
		    		$patient_id = $_POST['patient_id_img'];
		    		$file = $_FILES['hx_med_list_file'];
		    		$fileName = $_FILES['hx_med_list_file']['name'];
		    		$fileType = $_FILES['hx_med_list_file']['type'];
		    		$fileError = $_FILES['hx_med_list_file']['error'];
		    		$fileSize = $_FILES['hx_med_list_file']['size'];
		    		$fileTmpName = $_FILES['hx_med_list_file']['tmp_name'];

		    		$fileExt = explode('.', $fileName);
		    		$fileActualExt = strtolower(end($fileExt));

		    		$allowed = array('jpg', 'jpeg', 'png', 'pdf');

		    		if (in_array($fileActualExt, $allowed)) {
		    			if ($fileError === 0) {
		    				if ($fileSize < 1000000) 
							{
		    					$fileNameNew = $patient_id."_".uniqid('',true).".".$fileActualExt;
		    					//$fileNameNew = uniqid('',true).".".$fileActualExt;
		    					$fileDestination = $_SERVER['DOCUMENT_ROOT'].'/img/history/'.$fileNameNew;
		    					$fileUrl = '/img/history/'.$fileNameNew;
								//!!! NEW LINE !!!
								$fileDestination = str_replace('\\','/',$fileDestination);
								$fileUrl = str_replace('\\','/',$fileUrl);
		    					move_uploaded_file($fileTmpName, $fileDestination);
		    					$query = "INSERT INTO `medical_hx_img`(`company_id`,`branch_id`,`attend_id`, `patient_id`, `img`, 
								`img_url`,`created_by`,`created_datetime`) 
								VALUES ('$company_id','$branch_id','$attend_id', '$patient_id', '$fileDestination','$fileUrl',
								'$user_id',NOW())";
			    				mysqli_query($con, $query);
		    					header("Location: /layout/attendance/history_sheet.php?uploadsuccess");
		    				} 
							else 
							{
		    					echo "Your file is too big";
		    				}
		    				
		    			} 
						else 
						{
		    				echo "There was an error uploading your file";
		    			}
		    			
		    		}
		    		else
		    		{
		    			echo "You cannot upload files of this type";
		    		}
		    	} 
		    }

		    function history_medical_img_display()
