			function delete_diagnosis_attend()
			{
				global $con;
				$diagnosis_list_id = $_POST['diagnosis_list_id'];
				$attend_id = $_POST['attend_id'];

				$query_druglist = "SELECT * FROM `drug_list` WHERE `attend_id`='$attend_id'";
				$query_run_druglist = mysqli_query($con, $query_druglist);
			    if (!empty($query_run_druglist) && mysqli_num_rows($query_run_druglist) > 0)
			    {
					$query_select = "SELECT * FROM `diagnosis_list` WHERE `attend_id`='$attend_id'";
					$query_run_select = mysqli_query($con, $query_select);
					if (!empty($query_run_select) && mysqli_num_rows($query_run_select) > 1)
					{
						$query = "DELETE FROM `diagnosis_list` WHERE diagnosis_list_id='$diagnosis_list_id'";
						$query_run = mysqli_query($con, $query);
						if ($query_run)
						{
							$query = "DELETE FROM `stat_incidence_of_diseases` WHERE diag_list_id='$diagnosis_list_id'";
							$query_run = mysqli_query($con, $query);
							if ($query_run)
							{
								echo "deleted";
							};
						}
						else
						{
							echo "aborted";
						};
					}
					else
					{
						echo "single";
					};
				}
				else
				{
					$query = "DELETE FROM `diagnosis_list` WHERE diagnosis_list_id='$diagnosis_list_id'";
					$query_run = mysqli_query($con, $query);
					if ($query_run)
					{
						$query = "DELETE FROM `stat_incidence_of_diseases` WHERE diag_list_id='$diagnosis_list_id'";
						$query_run = mysqli_query($con, $query);
						if ($query_run)
						{
							echo "deleted";
						};
					}
					else
					{
						echo "aborted";
					};
				};
			}

