				'$bp_post','$weight_pre','$weight_post','$pulse_pre','$pulse_post','$bvp','$standing_bp',
				'$machine_no','$conductivity','$auto_test','$alarm_test','$na','$creat','$glue','$k',
				'$urea','$hb','$heart','$lungs','$gi','$vascular_access','$gait','$br_others','$fistula','$graft',
				'$needle_size','$perm_cath','$vascath','$shunt','$comment','$assessment_pre',
				'$assessment_post','$rbs_time','$rbs_value','$rbs_action','$connecting_nurse',
				'$disconnecting_nurse','$user_id',NOW())";
				$query_run = mysqli_query($con, $query);
				
