			function select_drug_attend()
			{
				global $con;
				$drug_id = $_POST['drug_id'];
				$drug_data=array();
				$query = "SELECT * FROM stock_items WHERE stock_item_id='$drug_id'";
				$result = mysqli_query($con,$query);
				while($row = mysqli_fetch_assoc($result))
				{
					array_push($drug_data, 
						$row['gender'],
						$row['age_from'],
						$row['age_to'],
						$row['block_neg'],
						$row['expiry_date'],
						$row['batch'],
						$row['days_prompt']
					);
				}
				 echo json_encode($drug_data);
			}

