			function view_drug_history()
			{
				global $con;
			    $patient_id = $_POST['patient_id'];
			    $sponsor_id = $_SESSION['sponsor'];
				$private_price = 0;
				$private_price_top = 0;
				$price_nhis = 0;
				$price_topup_nhis = 0;
				$value = "";
				$value = '<table class="table table-hover table-bordered table-sm" width="100%" cellspacing="0">
			        <thead>
			            <tr>
			                <th>Date</th>
			                <th>Drug</th>
			                <th>Qty Presc.</th>
			                <th>Dosage</th>
			            </tr>
			        </thead>
			        <tbody class="pv-table-body">';
				$query = "SELECT * FROM drug_list WHERE patient_id='$patient_id' ORDER BY date DESC";
				$query_run = mysqli_query($con,$query);
				$i = 0;
				if (mysqli_num_rows($query_run) > 0)
	            {
					while($row=mysqli_fetch_assoc($query_run))
					{
						$i++;
						$drug_id = $row['drug_id'];
						$query_drug = "SELECT * FROM stock_items WHERE stock_item_id='$drug_id'";
						$query_run_drug = mysqli_query($con, $query_drug);
						$row_drug=mysqli_fetch_assoc($query_run_drug);
						$drug_id = $row_drug['stock_item_id'];
						if($sponsor_id !=1 && $sponsor_id !=2)
						{
							$query_pl = "SELECT * FROM price_list WHERE ledger_id='$sponsor_id' AND item_id='$drug_id' AND category_id=2";
							$query_run_pl = mysqli_query($con, $query_pl);
							if (mysqli_num_rows($query_run_pl) > 0)
							{
								while($row_pl = mysqli_fetch_assoc($query_run_pl))
								{
									$private_price = $row_pl['price'];
									$private_price_top = $row_pl['price_topup'];
									$price_topup_nhis = 0;
									$price_nhis = 0;
								};
							}
							else
							{
								$private_price = $row['price_prvt'];
								$private_price_top = 0;
								$price_topup_nhis = 0;
								$price_nhis = 0;
							};
						}
						else if($sponsor_id == 2)
						{
							if(isset($row['nhis_id']))
							{
								$nhis_id = $row['nhis_id'];
								$query_nhis = "SELECT * FROM nhis WHERE nhis_id ='$nhis_id'";
								$query_run_nhis = mysqli_query($con, $query_nhis);
								if(isset($query_run_nhis))
								{
									$row_nhis = mysqli_fetch_assoc($query_run_nhis);
									if(isset($row_nhis['price_topup']))
									{
										$price_topup_nhis = $row_nhis['price_topup'];
									}
									else
									{
										$price_topup_nhis = 0;
									};
									if(isset($row_nhis['price']))
									{
										$price_nhis = $row_nhis['price'];
									}
									else
									{
										$price_nhis = 0;
									};
								}
								else
								{
									$price_topup_nhis = 0;
									$price_nhis = 0;
								};
									$private_price = 0;
									$private_price_top = 0;
							};
						};
						
						$drug_list_id = $row['drug_list_id'];
						$query_ddl = "SELECT drug_id FROM  drug_dispense_list WHERE drug_presc_id='$drug_id' AND drug_list_id='$drug_list_id'";
						$query_run_ddl = mysqli_query($con, $query_ddl);
						if(mysqli_num_rows($query_run_ddl) > 0)
						{
							$sup_drugs = '';
							while($row_ddl=mysqli_fetch_assoc($query_run_ddl))
							{
								$drug_id_ddl = $row_ddl['drug_id'];
								$query_drug_ddl = "SELECT * FROM stock_items WHERE stock_item_id='$drug_id_ddl'";
								$query_run_drug_ddl = mysqli_query($con, $query_drug_ddl);
								$row_drug_ddl = mysqli_fetch_assoc($query_run_drug_ddl);
								$sup_drugs .= $row_drug_ddl['stock_item'].'<br>';
							};
						}
						else
						{
							$sup_drugs = 'Not dispensed';
						};

						$value.='<tr id="'.$i.'">
							<td>'.$row['date'].'</td>
							<td>
								<a href="#" id="btn_save_drug_hx_item" class="btn_save_drug_hx_item"
									data-id="'.$row_drug['stock_item_id'].'"
									data-id1="'.$row_drug['gender'].'"
									data-id2="'.$row_drug['age_from'].'"
									data-id3="'.$row_drug['age_to'].'"
									data-id4="'.$row_drug['price_cash'].'"
									data-id5="'.$private_price.'"
									data-id6="'.$private_price_top.'"
									data-id7="'.$sponsor_id.'"
									data-id8="'.$price_nhis.'"
									data-id9="'.$price_topup_nhis.'"
									data-id10="'.$row['qty_presc'].'"
									data-id11="'.$row['dosage'].'"
									data-id12="'.$i.'"
								>'.$row_drug['stock_item'].'</strong><br><small>'.$sup_drugs.'</a></td>
							<td>'.$row['qty_presc'].'</td>
							<td>'.$row['dosage'].'</td>
						</tr>
						<tr>
							<td colspan="4">Remarks:'.$row['remarks'].'</td>
						</tr>';
					};
				};
					$value.='</tbody>
				</table>';
				echo $value;
			}

			function drug_attend_set_dispensing_company()
			{
				global $con;
				$company_id = $_POST['company_id'];
				$attend_id = $_SESSION['attend_id'];
				$_SESSION['dispensing_company'] = $_POST['company_id'];

				$query = "UPDATE attendance SET dispensing_company='$company_id' WHERE attend_id='$attend_id'";
				$query_run = mysqli_query($con,$query);

				if($query_run)
				{
					$value ='<select class="form-control bg-light" name="dispensing_company" id="dispensing_company"> 
						<option value="0">Select Dispenser</option>';
						
						$sql_comp="SELECT * FROM company";
						$result_comp = mysqli_query($con, $sql_comp);
						while($row_comp = mysqli_fetch_array($result_comp))
						{
							if($row_comp['company_id'] == $company_id)
							{
								$value .='<option value = "'.$row_comp['company_id'].'" selected="selected">'.$row_comp['trading_name'].'</option>';
							}
							else
							{
								$value .='<option value = "'.$row_comp['company_id'].'">'.$row_comp['trading_name'].'</option>';
							};
						};
					$value .= '</select>';
				};

				echo $value;
			}

			function set_drug_dispense_modal()
			{
				global $con;
				$drug_id = $_POST['drug_id'];
				$drug_list_id = $_POST['drug_list_id'];
				$warehouse = $_SESSION['warehouse_id'];
				$start_date = date('2000-01-01');
				$end_date = date('Y-m-d');
				$drug_data = array();

				$query = "SELECT SUM(qty) AS total_qty_dispensed FROM drug_dispense_list WHERE drug_list_id='$drug_list_id' AND drug_presc_id='$drug_id'";
				$query_run = mysqli_query($con,$query);
				$row_dc=mysqli_fetch_assoc($query_run);
				if($row_dc['total_qty_dispensed'] < 1 || $row_dc['total_qty_dispensed'] == null)
				{
					$total_qty_dispensed = 0;
				}
				else
				{
					$total_qty_dispensed = $row_dc['total_qty_dispensed'];
				}

				$query = "SELECT * FROM stock_items WHERE stock_item_id='$drug_id'";
				$result = mysqli_query($con,$query);
				
				//LOCATION_BALANCE
					$query_lb = "SELECT item_id, SUM(qty_out) AS qty_out, SUM(qty_in) AS qty_in FROM
					(SELECT con_id AS item_id, qty_issued AS qty_out, 0 AS qty_in FROM consumable_list WHERE date BETWEEN 
					'$start_date' AND '$end_date' AND con_id = '$drug_id' AND warehouse_id = '$warehouse' AND qty_issued > 0

					UNION ALL SELECT drug_id AS item_id,0 AS qty_out, qty AS qty_in FROM drug_patient_returns WHERE date BETWEEN 
					'$start_date' AND '$end_date' AND drug_id = '$drug_id' AND warehouse_id = '$warehouse' AND qty > 0

					UNION ALL SELECT drug_id AS item_id, qty AS qty_out, 0 AS qty_in FROM drug_dispense_list WHERE date BETWEEN '$start_date' AND 
					'$end_date' AND drug_id = '$drug_id' AND warehouse_id = '$warehouse' AND qty > 0 

					UNION ALL SELECT stock_item_id AS item_id, qty AS qty_out, 0 AS qty_in FROM stock_sales_items WHERE date BETWEEN '$start_date' AND 
					'$end_date' AND stock_item_id = '$drug_id' AND warehouse_id = '$warehouse' AND qty > 0

					UNION ALL SELECT stock_item_id AS item_id, qty_out AS qty_out, 0 AS qty_in FROM stock_adjustment_items WHERE  date BETWEEN 
					'$start_date' AND '$end_date' AND stock_item_id = '$drug_id' AND warehouse_id = '$warehouse' AND qty_out > 0
					
					UNION ALL SELECT stock_item_id AS item_id, qty_transferred AS qty_out, 0 AS qty_in FROM stock_transfer_items WHERE 
					date_trans BETWEEN '$start_date' AND '$end_date' AND stock_item_id = '$drug_id' AND 
					warehouse_id = '$warehouse' AND qty_transferred > 0
					
					UNION ALL SELECT stock_item_id AS item_id, 0 AS qty_out, qty_in AS qty_in FROM stock_adjustment_items WHERE date BETWEEN 
					'$start_date' AND '$end_date' AND stock_item_id = '$drug_id' AND warehouse_id = '$warehouse' AND qty_in > 0
					
					UNION ALL SELECT stock_item_id AS item_id, 0 AS qty_out, qty_received AS qty_in FROM stock_transfer_items WHERE date_trans 
					BETWEEN '$start_date' AND '$end_date' AND stock_item_id = '$drug_id' AND warehouse_id = '$warehouse' AND qty_received > 0
					
					UNION ALL SELECT item_id AS item_id, 0 AS qty_out, qty AS qty_in FROM purchase_items WHERE date BETWEEN '$start_date' 
					AND '$end_date' AND item_id = '$drug_id' AND warehouse_id = '$warehouse' AND qty > 0) 
					AS d GROUP BY item_id";

					$query_run_lb = mysqli_query($con, $query_lb);
					if(!empty($query_run_lb) && mysqli_num_rows($query_run_lb) > 0)
					{
						while($row_lb = mysqli_fetch_assoc($query_run_lb))
						{
							$location_balance = $row_lb['qty_in'] - $row_lb['qty_out'];
						};
					}
					else
					{
						$location_balance = 0;
					};
				
					//ITEM_BALANCE
						$query_ib = "SELECT item_id, SUM(qty_out) AS qty_out, SUM(qty_in) AS qty_in FROM
						(SELECT con_id AS item_id, qty_issued AS qty_out, 0 AS qty_in FROM consumable_list WHERE date BETWEEN 
						'$start_date' AND '$end_date' AND con_id = '$drug_id' AND qty_issued > 0
	
						UNION ALL SELECT drug_id AS item_id,0 AS qty_out, qty AS qty_in FROM drug_patient_returns WHERE date BETWEEN 
						'$start_date' AND '$end_date' AND drug_id = '$drug_id' AND qty > 0
	
						UNION ALL SELECT drug_id AS item_id, qty AS qty_out, 0 AS qty_in FROM drug_dispense_list WHERE date BETWEEN '$start_date' AND 
						'$end_date' AND drug_id = '$drug_id' AND qty > 0 
	
						UNION ALL SELECT stock_item_id AS item_id, qty AS qty_out, 0 AS qty_in FROM stock_sales_items WHERE date BETWEEN '$start_date' AND 
						'$end_date' AND stock_item_id = '$drug_id' AND qty > 0
	
						UNION ALL SELECT stock_item_id AS item_id, qty_out AS qty_out, 0 AS qty_in FROM stock_adjustment_items WHERE  date BETWEEN 
						'$start_date' AND '$end_date' AND stock_item_id = '$drug_id' AND qty_out > 0
						
						UNION ALL SELECT stock_item_id AS item_id, qty_transferred AS qty_out, 0 AS qty_in FROM stock_transfer_items WHERE 
						date_trans BETWEEN '$start_date' AND '$end_date' AND stock_item_id = '$drug_id' AND qty_transferred > 0
						
						UNION ALL SELECT stock_item_id AS item_id, 0 AS qty_out, qty_in AS qty_in FROM stock_adjustment_items WHERE date BETWEEN 
						'$start_date' AND '$end_date' AND stock_item_id = '$drug_id' AND qty_in > 0
						
						UNION ALL SELECT stock_item_id AS item_id, 0 AS qty_out, qty_received AS qty_in FROM stock_transfer_items WHERE date_trans 
						BETWEEN '$start_date' AND '$end_date' AND stock_item_id = '$drug_id' AND qty_received > 0
						
						UNION ALL SELECT item_id AS item_id, 0 AS qty_out, qty AS qty_in FROM purchase_items WHERE date BETWEEN '$start_date' 
						AND '$end_date' AND item_id = '$drug_id' AND qty > 0) 
						AS d GROUP BY item_id";
	
						$query_run_ib = mysqli_query($con, $query_ib);
						if(!empty($query_run_lb) && mysqli_num_rows($query_run_ib) > 0)
						{
							while($row_ib = mysqli_fetch_assoc($query_run_ib))
							{
								$item_balance = $row_ib['qty_in'] - $row_ib['qty_out'];
							};
						}
						else
						{
							$item_balance = 0;
						};

				$row = mysqli_fetch_assoc($result);
					array_push($drug_data, 
						$total_qty_dispensed,
						$row['block_neg'],
						$row['expiry_date'],
						$row['days_to_prompt'],
						$row['batch'],
						$location_balance,
						$item_balance
					);
				 echo json_encode($drug_data);
			}

