			function delete_drug_dispensed()
			{
				global $con;
				$drug_disp_list_id = $_POST['drug_disp_list_id'];
				$drug_list_id = $_POST['drug_list_id'];
				$attend_id = $_POST['attend_id'];
				
				$query_dd = "SELECT SUM(qty) AS total_qty_dispensed, SUM(amt_cash) AS total_cash_amount
				FROM `drug_dispense_list` WHERE `drug_list_id`='$drug_list_id'";
				$query_run_dd = mysqli_query($con, $query_dd);
				if (mysqli_num_rows($query_run_dd) > 0)
				{
					$row_dd = mysqli_fetch_assoc($query_run_dd);
					$total_qty_dispensed = $row_dd['total_qty_dispensed'];
					$total_cash_amount = $row_dd['total_cash_amount'];
				}
				else
				{
					$total_qty_dispensed = 0;
					$total_cash_amount = 0;
				};

				$query_ddl = "SELECT * FROM `drug_dispense_list` WHERE `drug_disp_list_id`='$drug_disp_list_id'";
				$query_run_ddl = mysqli_query($con, $query_ddl);
				if (!empty($query_run_ddl) && mysqli_num_rows($query_run_ddl) > 0)
				{
					$row_ddl = mysqli_fetch_assoc($query_run_ddl);
					$qty_dispensed = $row_ddl['qty'];
					$amount_dispensed = $row_ddl['amt_cash'];
				}
				else
				{
					$qty_dispensed = 0;
					$amount_dispensed = 0;
				};
				$qty_left = $total_qty_dispensed - $qty_dispensed;
				$cash_left = $total_cash_amount - $amount_dispensed;

			    $query = "DELETE FROM `drug_dispense_list` WHERE drug_disp_list_id='$drug_disp_list_id'";
			    $query_run = mysqli_query($con, $query);
			    if ($query_run)
			    {
					$query_dl = "UPDATE `drug_list` SET `qty_dispensed`='$qty_left',`amount_cash`='$cash_left' 
					WHERE `drug_list_id`='$drug_list_id' AND `drug_id`='$drug_id'";
				   	mysqli_query($con, $query_dl);

			        $query_trans_del = "DELETE FROM `transactions` WHERE `attend_id`='$attend_id' AND `category_id`=2 AND `item_list_id`='$drug_list_id' AND drug_disp_list_id='$drug_disp_list_id'";
					mysqli_query($con, $query_trans_del);
			    }
			    else
			    {
			        echo "Drug NOT Deleted";
			    };
			}

