			function item_balance($item_id, $warehouse)
			{
				global $con;
				$start_date = '2000-01-01';
				$end_date = date('Y-m-d');
				$query ="SELECT item_id, SUM(qty_in) AS qty_in, SUM(qty_out) AS qty_out FROM
				(SELECT con_id AS item_id, qty_issued AS qty_out, 0 AS qty_in FROM consumable_list 
				WHERE con_id='$item_id' AND date BETWEEN '$start_date' AND '$end_date' AND warehouse_id ='$warehouse'
				UNION ALL SELECT drug_id AS item_id, 0 AS qty_out, qty AS qty_in FROM drug_patient_returns 
				WHERE drug_id='$item_id' AND date BETWEEN '$start_date' AND '$end_date' AND warehouse_id ='$warehouse'
				UNION ALL SELECT drug_id AS item_id, qty AS qty_out, 0 AS qty_in FROM drug_dispense_list 
				WHERE drug_id='$item_id' AND date BETWEEN '$start_date' AND '$end_date' AND warehouse_id ='$warehouse'
				UNION ALL SELECT stock_item_id AS item_id, qty AS qty_out, 0 AS qty_in FROM stock_sales_items 
				WHERE stock_item_id='$item_id' AND date BETWEEN '$start_date' AND '$end_date' AND warehouse_id ='$warehouse'
				UNION ALL SELECT stock_item_id AS item_id, qty_out AS qty_out, 0 AS qty_in FROM stock_adjustment_items 
				WHERE stock_item_id='$item_id' AND  date BETWEEN '$start_date' AND '$end_date' AND warehouse_id ='$warehouse'
				UNION ALL SELECT stock_item_id AS item_id, qty_transferred AS qty_out, 0 AS qty_in FROM stock_transfer_items 
				WHERE stock_item_id='$item_id' AND date_trans BETWEEN '$start_date' AND '$end_date' AND warehouse_id ='$warehouse'
				UNION ALL SELECT stock_item_id AS item_id, 0 AS qty_out, qty_in AS qty_in FROM stock_adjustment_items 
				WHERE stock_item_id='$item_id' AND date BETWEEN '$start_date' AND '$end_date' AND warehouse_id ='$warehouse'
				UNION ALL SELECT stock_item_id AS item_id, 0 AS qty_out, qty_received AS qty_in FROM stock_transfer_items 
				WHERE stock_item_id='$item_id' AND date_trans BETWEEN '$start_date' AND '$end_date' AND warehouse_id ='$warehouse'
				UNION ALL SELECT item_id AS item_id, 0 AS qty_out, qty AS qty_in FROM purchase_items 
				WHERE item_id='$item_id' AND date BETWEEN '$start_date' AND '$end_date' AND warehouse_id ='$warehouse') AS d GROUP BY item_id";
				
				$query_run = mysqli_query($con, $query);
				if (mysqli_num_rows($query_run) > 0)
				{
					while($row = mysqli_fetch_assoc($query_run))
					{
						$cls_bal = $row['qty_in'] - $row['qty_out'];
					}
				};
				return $cls_bal;
			}
			
