				$result = mysqli_query($con,$query);
				while($row=mysqli_fetch_assoc($result))
				{
					array_push($Data, 
						$row['service_list_id'],
						$row['service_id'],
						$row['attend_id'],
						$row['patient_id'],
						$row['date'],
						$row['qty'],
						$row['g_drg'],
						$row['price_cash'],
						$row['price_nhis'],
						$row['price_prvt'],
						$row['amount_cash'],
						$row['amount_nhis'],
						$row['amount_prvt'],
						$row['comment'],
						$row['doctor_id'],
						$row['ledger_id']
					);
				}
				 echo json_encode($Data);
			}

