					    $_SESSION['abortions'] = $row_abort['abortions'];

					    $query_spont = "SELECT COUNT(preg_id) AS spontaneous FROM pregnancies WHERE patient_id='$patient_id' AND method='ABORTION' AND labour_type='Spontaneous'";
