				    $bp_systolic = $_POST['pnc_bp_systolic'];
				    $bp_diastolic = $_POST['pnc_bp_diastolic'];
				    $weight = $_POST['pnc_weight'];
				    $pulse = $_POST['pnc_pulse'];
				    $temp = $_POST['pnc_temp'];
				    $urine_protein = $_POST['pnc_urine_protein'];
				    $urine_sugar = $_POST['pnc_urine_sugar'];
