		function receipt_new_payment_type()
		{
			global $con;
			$i = $_POST['i'];
			$value = '
			<tr id="pt'.$i.'">
				<td>
				<select class="form-control bg-light debit_ledger" name="debit_ledger[]" id="debit_ledger'.$i.'" data-id="'.$i.'"> 
					<option value="0">Please Select</option>';
					
						$sql="SELECT * FROM ledgers WHERE tb_4=6 ORDER BY ledger_desc ASC";
						$result = mysqli_query($con,$sql);
						while($row = mysqli_fetch_array($result))
						{
							$value .= '<option value = "'.$row['ledger_id'].'" >'.$row['ledger_desc'].'</option>';
						};
				
				$value .= '</select>
				</td>
				<td class = "action-td">
					<input type="text" name="receipt_payment_type_amt[]" class="form-control bg-light receipt_payment_type_amt amt-td" id="receipt_payment_type_amt'.$i.'" data-id="'.$i.'" style="border-width:0px">
				</td>
				<td class = "action-td">';
					if($i > 1)
					{
						$value .= '<a href="#" id="delete_receipt_payment_type" data-id="'.$i.'"><i class="fa fa-trash fa-sm"></i></a>';
					};
				$value .= '</td>
			</tr>';
			
			echo $value;
		}

