		function search_receipt_by_name()
		{
			global $con;
			$company_id = $_SESSION['company_id'];
			$user_branch_id = $_SESSION['branch_id'];
			$search = mysqli_real_escape_string($con, $_POST["search"]);
			$value = '';
                if ($_SESSION['user_type'] == 'Ultra_Super_User' OR $_SESSION['user_type'] == 'Super_User' OR ($_SESSION['user_type'] == 'Normal_User' AND $_SESSION['user_type_id'] == 3)) 
                {
					if(isset($search))
					{
						$query = "SELECT * FROM receipt WHERE (name LIKE '%".$search."%' AND company_id='$company_id') 
						OR (amount LIKE '%".$search."%' AND company_id='$company_id') ORDER BY date DESC";
					}
					else
					{
						$query = "SELECT * FROM receipt WHERE  company_id='$company_id' ORDER BY date DESC";
					}
                }
                else
                {
					if(isset($search))
					{
						$query = "SELECT * FROM receipt WHERE (name LIKE '%".$search."%' AND company_id='$company_id' AND branch_id = '$user_branch_id') 
				  		OR (amount LIKE '%".$search."%' AND company_id='$company_id' AND branch_id = '$user_branch_id') ORDER BY date DESC";
					}
					else
					{
						$query = "SELECT * FROM receipt WHERE company_id='$company_id' AND branch_id = '$user_branch_id' ORDER BY date DESC";
					};
                };
				$query_run = mysqli_query($con, $query);
				$value.='<table class="table table-hover table-bordered table-sm" id="receiptTable" width="100%" cellspacing="0">
				<thead>
