									$payment_led_dr = $_POST['payment_led_dr'][$i];
									$payment_dr_amt = $_POST['payment_dr_amt'][$i];
									$payment_dr_narration = $_POST['payment_dr_narration'][$i];

									$query_dr = "INSERT INTO `transactions`(
