		function save_purchase_invoice()
		{
			global $con;
			$purch_debit = $_POST['purch_debit'];
			$purch_credit = $_POST['purch_credit'];
			$purch_amount = $_POST['purch_amount'];
			$disc_perc = $_POST['purch_discount_perc'];
			$disc_amount = $_POST['purch_discount_amount'];
			$purch_supplied_by = $_POST['purch_supplied_by'];
			$purch_ref_no = $_POST['purch_ref_no'];
			$purch_date = $_POST['purch_date'];
			$purch_received_by = $_POST['purch_received_by'];
			$purch_narration = $_POST['purch_narration'];
			$warehouse = $_POST['purch_warehouse'];
			$company_id = $_SESSION['company_id'];
			$user_id = $_SESSION['user_id'];
			$branch_id = $_SESSION['branch_id'];
			$margin_branch = $_SESSION['margin_branch'];
			$margin_inter_branch = $_SESSION['margin_inter_branch'];

			$query = "INSERT INTO `purchases`(`company_id`, `date`, `ledger_debit`, `ledger_credit`, 
			`amount`, `reference_no`, `supplied_by`, `received_by`, `narration`, `branch_id`, 
			`discount_perc`, `discount_amount`,`created_by`, `created_datetime`, `warehouse_id`) 
			VALUES ('$company_id','$purch_date','$purch_debit','$purch_credit','$purch_amount',
			'$purch_ref_no','$purch_supplied_by','$purch_received_by','$purch_narration','$branch_id',
			'$disc_perc','$disc_amount','$user_id',NOW(),'$warehouse')";
			$query_run = mysqli_query($con, $query);

			if ($query_run) 
			{
				//POST TRANSACTION
					$query = "SELECT * FROM purchases ORDER BY purchase_id DESC";
					$result = mysqli_query($con,$query);
					$row = mysqli_fetch_assoc($result);
					$purchase_id = $row['purchase_id'];

					$query_dr = "INSERT INTO `transactions`(`company_id`,`purchase_id`,`ledger_id`, 
					`ledger_id_contra`, `date`, `amt`, `amt_debit`, `narration`,`branch_id`, `created_by`, 
					`created_datetime`) VALUES ('$company_id','$purchase_id','$purch_debit','$purch_credit',
					'$purch_date','$purch_amount','$purch_amount','$purch_narration','$branch_id','$user_id',
					NOW())";
					mysqli_query($con, $query_dr);

					$query_cr = "INSERT INTO `transactions`(`company_id`,`purchase_id`,`ledger_id`, 
					`ledger_id_contra`, `date`, `amt`, `amt_credit`, `narration`, `branch_id`, `created_by`, 
					`created_datetime`) VALUES ('$company_id','$purchase_id','$purch_credit','$purch_debit',
					'$purch_date','$purch_amount','$purch_amount','$purch_narration','$branch_id','$user_id',
					NOW())";
					mysqli_query($con, $query_cr);

				//DISCOUNT
					if($disc_amount > 0)
					{
						$query_dr = "INSERT INTO `transactions`(`company_id`,`purchase_id`,`ledger_id`, 
						`ledger_id_contra`, `date`, `amt`, `amt_debit`, `narration`,`branch_id`, `created_by`, 
						`created_datetime`) VALUES ('$company_id','$purchase_id','$purch_credit',108,
						'$purch_date','$purch_amount','$purch_amount','$purch_narration','$branch_id','$user_id',
						NOW())";
						mysqli_query($con, $query_dr);

						$query_cr = "INSERT INTO `transactions`(`company_id`,`purchase_id`,`ledger_id`, 
						`ledger_id_contra`, `date`, `amt`, `amt_credit`, `narration`, `branch_id`, `created_by`, 
						`created_datetime`) VALUES ('$company_id','$purchase_id',108,'$purch_debit',
						'$purch_date','$purch_amount','$purch_amount','$purch_narration','$branch_id','$user_id',
						NOW())";
						mysqli_query($con, $query_cr);
					};

				//PRICE_LIST
					$query_pl = "SELECT * FROM price_level WHERE company_id='$company_id'";
					$result_pl = mysqli_query($con,$query_pl);
					if(!empty($result_pl) && mysqli_num_rows($result_pl) > 0)
					{
						$row_pl = mysqli_fetch_assoc($result_pl);
						$price_level_id = $row_pl['price_level_id'];
						$price_level_status = 'old_price_list';
					}
					else
					{
						$query_pl = "INSERT INTO `price_level`(`price_level`,`company_id`,`branch_id`,`date`,`created_by`,
						`created_datetime`) VALUES ('$price_level','$company_id','$branch_id','$purch_date','$user_id',NOW())";
						$query_run_pl = mysqli_query($con, $query_pl);
						if ($query_run_pl) 
						{
							//ADD PRICE LIST
								$query_pls = "SELECT * FROM price_level WHERE `company_id`='$company_id' ORDER BY price_level_id DESC";
								$result_pls = mysqli_query($con,$query_pls);
								$row_pls = mysqli_fetch_assoc($result_pls);
								$price_level_id = $row_pls['price_level_id'];
								$price_level_status = 'new_price_list';
						}
					};

				//PURCHASE_ITEM_LIST
					$number_as = count($_POST["purch_desc"]);
					if($number_as > 0)  
					{  
						for($i=0; $i<$number_as; $i++)  
						{  
							if(trim($_POST["purch_desc"][$i] !== '') && trim($_POST["purch_desc"][$i] !== 0))  
							{  
								$purch_desc = $_POST['purch_desc'][$i];
								$purch_loc = $_POST['purch_loc'][$i];
								$purch_qty = $_POST['purch_qty'][$i];
								$purch_price = $_POST['purch_price'][$i];
								$purch_amt = $_POST['purch_amt'][$i];
								$purch_selling_price = $_POST['purch_selling_price'][$i];
								$purch_batch = $_POST['purch_batch'][$i];
								$purch_expiry_date = $_POST['purch_expiry_date'][$i];
								$purch_cat_id = 2;
								//$purch_cat_id = $_POST['purch_cat_id'][$i];
								$selling_price = $_POST['purch_price'][$i] + ($_POST['purch_price'][$i] * $margin_branch);
								$selling_price_branch = $_POST['purch_price'][$i] + ($_POST['purch_price'][$i] * $margin_inter_branch);
								$query = "INSERT INTO `purchase_items`
								(`company_id`, `purchase_id`, `item_id`, `category_id`, `warehouse_id`, `date`, `price`, `amount`, 
								`batch`, `expiry_date`, `qty`, `branch_id`) VALUES 
								('$company_id','$purchase_id','$purch_desc','$purch_cat_id','$warehouse','$purch_date',
								'$purch_price','$purch_amt','$purch_batch','$purch_expiry_date','$purch_qty','$branch_id')";
								$query_run = mysqli_query($con, $query);
								
								if($query_run)
								{
									if($purch_selling_price > 0)
									{
										$query_drug = "UPDATE `stock_items` SET `price_cash`='$purch_selling_price' WHERE `stock_item_id`='$purch_desc'";
										mysqli_query($con, $query_drug);
									};

									if($price_level_status == 'new_price_list')
									{
										$query = "INSERT INTO `price_list`(`price_level_id`,`company_id`,`branch_id`,`stock_item_id`,
										`price`,`price_branch`,`date`,`created_by`, `created_datetime`) VALUES ('$price_level_id','$company_id',
										'$branch_id','$purch_desc','$selling_price','$selling_price_branch','$purch_date','$user_id',NOW())";
										mysqli_query($con, $query);
									}
									else
									{
										$query_pls = "SELECT * FROM price_list WHERE `price_level_id`='$price_level_id' AND 
										`stock_item_id`='$purch_desc'";
										$result_pls = mysqli_query($con,$query_pls);
										if(!empty($result_pls) && mysqli_num_rows($result_pls) > 0)
										{
											$row_pls = mysqli_fetch_assoc($result_pls);
											$price_list_id = $row_pls['price_list_id'];

											$query = "UPDATE `price_list` SET `price`='$selling_price', `price_branch`='$selling_price_branch' WHERE `price_list_id`='$price_list_id'";
											mysqli_query($con, $query);
										}
										else
										{
											$query = "INSERT INTO `price_list`(`price_level_id`,`company_id`,`branch_id`,`stock_item_id`,
											`price`,`price_branch`,`date`,`created_by`, `created_datetime`) VALUES ('$price_level_id','$company_id',
											'$branch_id','$purch_desc','$selling_price','$selling_price_branch','$purch_date','$user_id',NOW())";
											mysqli_query($con, $query);
										};
									};
								};
							};
						}; 
					};
			};
		}

