		function stock_sales_get_customer_info()
		{
			global $con;
			$search = $_POST['search'];
			$customer = array();
			$data = array();
			$query="SELECT * FROM customer WHERE phone_number LIKE '%".$search."%' OR id_number LIKE '%".$search."%'";
			$result = mysqli_query($con,$query);
			if(!empty($result) && mysqli_num_rows($result) > 0)
			{
				$row = mysqli_fetch_assoc($result);
				array_push($customer, 
					$row['customer_id'],
					$row['first_name'].' '.$row['last_name'],
					$row['date_of_birth'],
					$row['phone_number'],
					$row['id_number'],
					$row['gender'],
					$row['location'],
					$row['ledger_id']
				);
				$status = 'exist';
			}
			else
			{
				$status = 'empty';
			}

			array_push($data, $status, $customer);
			echo json_encode($data);
		}

