	    function update_stock_sales_invoice()
		{
			global $con;
			
			if(isset($_POST['stock_sales_id'])){$stock_sales_id = $_POST['stock_sales_id'];}else{$stock_sales_id = 0;};
			if(isset($_POST['stock_sales_order_id'])){$sales_order_id = $_POST['stock_sales_order_id'];}else{$sales_order_id = 0;};
			if(isset($_POST['stock_sales_req_id'])){$stock_req_id = $_POST['stock_sales_req_id'];}else{$stock_req_id = 0;};
			$sales_type = $_POST['stock_sales_invoice_type'];
			$sales_credit = $_POST['stock_sales_credit'];
			$receiving_warehouse = $_POST['stock_sales_branch_warehouse_id'];
			$date = $_POST['stock_sales_date'];
			$amount = $_POST['stock_sales_amount'];
			$discount = $_POST['stock_sales_discount_amount'];
			$net_amount = $_POST['stock_sales_net_amount'];
			$warehouse_id = $_POST['stock_sales_warehouse_id'];
			$buying_branch = $_POST['stock_sales_buying_branch'];

			//PAYMENT_OPTIONS
				$payment_option_total = $_POST['payment_option_total'];
				$cash_tendered = $_POST['payment_option_cash_tendered'];
				$change = $_POST['payment_option_change'];

			//CUSTOMER_DETAILS
				$customer_id = $_POST['stock_sales_customer_id'];
				$customer_telephone = $_POST['stock_sales_customer_telephone'];
				$customer_name = $_POST['stock_sales_customer_name'];
				$membership_no = $_POST['stock_sales_membership_no'];
				$date_of_birth = $_POST['stock_sales_date_of_birth'];
				$age = age($date_of_birth);
				$gender = $_POST['stock_sales_gender'];
				$location = $_POST['stock_sales_location'];
				$insurance_company = $_POST['stock_sales_insurance_company'];
				if($customer_id > 0 )
				{
					$query = "UPDATE `customer` SET `first_name`='$customer_name',`date_of_birth`='$date_of_birth', 
					`phone_number`='$customer_telephone', `id_number`='$membership_no', `location`='$location', 
					`ledger_id`='$insurance_company', `gender`='$gender',`altered_by`='$user_id', `altered_datetime`=NOW() 
					WHERE `customer_id`='$customer_id'";
					mysqli_query($con,$query);
				}
				else
				{
					$query = "INSERT INTO `customer`(
					`company_id`,`branch_id`,`first_name`,`date_of_birth`, `phone_number`, `id_number`, `location`, 
					`ledger_id`, `gender`,`created_by`, `created_datetime`) VALUES (
					'$company_id','$branch_id','$customer_name','$date_of_birth','$customer_telephone','$membership_no',
					'$location','$insurance_company','$gender','$user_id',NOW())";
					
					$result = mysqli_query($con,$query);
					if($result)
					{
						$query = "SELECT * FROM customer ORDER BY customer_id DESC";
						$result = mysqli_query($con,$query);
						$row = mysqli_fetch_assoc($result);
						$customer_id = $row['customer_id'];
					};
				};

			if(isset($narration) && $narration !='')
			{
				$narration = $narration;
			}
			else
			{
				$narration = "GOODS SOLD TO ".$customer_name;
			};

			$company_id = $_SESSION['company_id'];
			$branch_id = $_SESSION['branch_id'];
			$user_id = $_SESSION['user_id'];
			$full_name = $_SESSION['full_name'];
			$margin_inter_branch = $_SESSION['margin_inter_branch'];

			$query = "SELECT sno FROM stock_sales WHERE company_id = '$company_id' 
			AND branch_id = '$branch_id' ORDER BY sno DESC";
			$result = mysqli_query($con,$query);
			if (mysqli_num_rows($result) > 0)
			{
				$row = mysqli_fetch_assoc($result);
				$sno = $row['sno'] + 1;
			}
			else
			{
				$sno = 1;
			};

			$query = "UPDATE  `stock_sales`SET
			`date`='$date', `ledger_credit`='$sales_credit', `amount`='$amount', `warehouse_id`='$warehouse_id',
			`supplied_by`='$full_name', `received_by`='$customer_name', `narration`='$narration', 
			`customer_id`='$customer_id', `age`='$age', `id_number`='$membership_no',`total_payment_option`='$payment_option_total', 
			`cash_tendered`='$cash_tendered', `balance`='$change', `total_invoice_value`='$amount', 
			`discount`='$discount', `net_amount`='$net_amount',`altered_by`='$user_id', `altered_datetime`=NOW(), 
			`insurance_id`='$insurance_company', `type`='$sales_type', 
			`company_id_to`='$buying_branch', `sales_order_id`='$sales_order_id', `stock_req_id`='$stock_req_id' 
			WHERE `stock_sales_id`='$stock_sales_id'";
			$query_run = mysqli_query($con, $query);

			if ($query_run) 
			{
				//POST TRANSACTION
					$query_trans_del = "DELETE FROM `transactions` WHERE `stock_sales_id`='$stock_sales_id'";
					mysqli_query($con, $query_trans_del);
					$query_trans_del = "DELETE FROM `purchases` WHERE `stock_sales_id`='$stock_sales_id'";
					mysqli_query($con, $query_trans_del);
					$query_trans_del = "DELETE FROM `purchase_items` WHERE `stock_sales_id`='$stock_sales_id'";
					mysqli_query($con, $query_trans_del);
					$query_trans_del = "DELETE FROM `stock_sales_items` WHERE `stock_sales_id`='$stock_sales_id'";
					mysqli_query($con, $query_trans_del);
						
					$ledger_as = count($_POST["payment_option_ledger_id"]);  
					if($ledger_as > 0)  
					{  
						for($i = 0; $i < $ledger_as; $i++)  
						{  
							if(trim($_POST["payment_option_ledger_id"][$i] != '') && trim($_POST["payment_option_ledger_id"][$i] != 0))  
							{  
								$sales_debit = $_POST['payment_option_ledger_id'][$i];
								$sales_amount = $_POST['payment_option_ledger_amount'][$i];

								$query_dr = "INSERT INTO `transactions`(
								`company_id`,`branch_id`,`stock_sales_id`,`ledger_id`, `ledger_id_contra`, `date`, `amt`, 
								`amt_debit`, `narration`,`created_by`, `created_datetime`) VALUES (
								'$company_id','$branch_id','$stock_sales_id','$sales_debit','$sales_credit','$date',
								'$sales_amount','$sales_amount','$narration','$user_id',NOW())";
								mysqli_query($con, $query_dr);
			
								$query_cr = "INSERT INTO `transactions`(
								`company_id`,`branch_id`,`stock_sales_id`,`ledger_id`, `ledger_id_contra`, `date`, `amt`, 
								`amt_credit`, `narration`,`created_by`, `created_datetime`) VALUES (
								'$company_id','$branch_id','$stock_sales_id','$sales_credit','$sales_debit','$date',
								'$sales_amount','$sales_amount','$narration','$user_id',NOW())";
								mysqli_query($con, $query_cr);
							};
						};
					};

					if($discount > 0)
					{
						$query_dr = "INSERT INTO `transactions`(
						`company_id`,`branch_id`,`stock_sales_id`,`ledger_id`, `ledger_id_contra`, `date`, `amt`, 
						`amt_debit`, `narration`,`created_by`, `created_datetime`) VALUES (
						'$company_id','$branch_id','$stock_sales_id',109,'$sales_credit','$date',
						'$discount','$discount','$sales_narration','$user_id',NOW())";
						mysqli_query($con, $query_dr);

						$query_cr = "INSERT INTO `transactions`(
						`company_id`,`branch_id`,`stock_sales_id`,`ledger_id`, `ledger_id_contra`, `date`, `amt`, 
						`amt_credit`, `narration`,`created_by`, `created_datetime`) VALUES (
						'$company_id','$branch_id','$stock_sales_id','$sales_credit',109,'$date',
						'$discount','$discount','$sales_narration','$user_id',NOW())";
						mysqli_query($con, $query_cr);
					};

					$number_as = count($_POST["stock_sales_item_id"]);
					$_SESSION['no_of_items_sold'] = $number_as;
					if($number_as > 0)  
					{  
						for($i = 0; $i < $number_as; $i++)  
						{  
							if(trim($_POST["stock_sales_item_id"][$i] != '') && trim($_POST["stock_sales_item_id"][$i] > 0))  
							{
								$item_id = $_POST['stock_sales_item_id'][$i];
								$attend_id = $_POST['stock_sales_attend_id'][$i];
								$patient_id = $_POST['stock_sales_patient_id'][$i];
								$drug_list_id = $_POST['stock_sales_drug_list_id'][$i];
								$qty = $_POST['stock_sales_item_qty'][$i];
								$qty_billed = $_POST['stock_sales_item_billed_qty'][$i];
								$disc_perc = $_POST['stock_sales_item_disc_perc'][$i];
								$disc_amount = $_POST['stock_sales_item_disc_amt'][$i];
								$price = $_POST['stock_sales_item_price'][$i];
								$amount = $_POST['stock_sales_item_amt'][$i];

								$query = "INSERT INTO `stock_sales_items`
								(`company_id`,`branch_id`, `stock_sales_id`, `stock_item_id`, `warehouse_id`, `date`, `price`, `amount`, 
								`qty`,`created_by`, `created_datetime`,`qty_billed`,`perc_disc`,`amount_disc`,`sales_order_id`,`stock_req_id`,
								`attend_id`,`patient_id`,`drug_list_id`) VALUES 
								('$company_id','$branch_id','$stock_sales_id','$item_id','$warehouse_id','$date',
								'$price','$amount','$qty','$user_id',NOW(),'$qty_billed','$disc_perc','$disc_amount','$sales_order_id','$stock_req_id',
								'$attend_id','$patient_id','$drug_list_id')";
								mysqli_query($con, $query);
							}; 
						};
					};

					if($sales_type == 'new_branch_sales_invoice')
					{
						//RECEIVING_COMPANY
							$sql = "SELECT * FROM company WHERE company_id = '$buying_branch'";
							$result = mysqli_query($con,$sql);
							$row = mysqli_fetch_array($result);
							$receiving_company_type = $row['company_type_id'];

						//SELLING_COMPANY
							$company_id = $_SESSION['company_id'];
							$sql = "SELECT * FROM company WHERE company_id = '$company_id'";
							$result = mysqli_query($con,$sql);
							$row = mysqli_fetch_array($result);
							$selling_company_type = $row['company_type_id'];

						$purch_debit = 17;
						$purch_credit = $_SESSION['company_ledger_id'];
						$purch_amount = $_POST['purch_amount'];
						$purch_supplied_by = $_SESSION['trading_name'];
						$purch_ref_no = $stock_sales_id;
						$purch_received_by = '';
						$purch_narration = 'INTER-BRANCH TRANSACTION';
						$user_id = $_SESSION['user_id'];
						$branch_id = $_SESSION['branch_id'];
						$margin_branch = $_SESSION['margin_branch'];
						$margin_inter_branch = $_SESSION['margin_inter_branch'];

						$query_br = "SELECT * FROM branch WHERE company_id='$buying_branch'";
						$result_br = mysqli_query($con,$query_br);
						if(!empty($result_br) && mysqli_num_rows($result_br) > 0)
						{
							$row_br = mysqli_fetch_assoc($result_br);
							$receiving_branch_id = $row_br['branch_id'];
						}
						else
						{
							$receiving_branch_id = 0;
						};

						$query = "INSERT INTO `purchases`(`company_id`,`sending_company_id`, `date`, `ledger_debit`, `ledger_credit`, 
						`amount`, `reference_no`, `supplied_by`, `received_by`, `narration`, `branch_id`, `sending_branch_id`, 
						`sending_branch_margin`, `created_by`, `created_datetime`, `stock_sales_id`, `stock_req_id`) 
						VALUES ('$buying_branch',
						'$company_id','$date','$purch_debit', '$purch_credit','$purch_amount','$purch_ref_no','$purch_supplied_by',
						'$purch_received_by','$purch_narration','$receiving_branch_id','$branch_id','$margin_inter_branch',
						'$user_id',NOW(),'$stock_sales_id','$stock_req_id')";
						$query_run = mysqli_query($con, $query);

						if ($query_run) 
						{
							$query = "SELECT * FROM purchases ORDER BY purchase_id DESC";
							$result = mysqli_query($con,$query);
							$row = mysqli_fetch_assoc($result);
							$purchase_id = $row['purchase_id'];
							
							$number_as = count($_POST["stock_sales_item_id"]);
							$_SESSION['no_of_items_sold'] = $number_as;
							if($number_as > 0)  
							{  
								for($i = 0; $i < $number_as; $i++)  
								{  
									if(trim($_POST["stock_sales_item_id"][$i] != '') && trim($_POST["stock_sales_item_id"][$i] > 0))  
									{  
										$purch_desc = $_POST['stock_sales_item_id'][$i];
										$purch_qty = $_POST['stock_sales_item_qty'][$i];
										$purch_price = $_POST['stock_sales_item_price'][$i];
										$purch_amt = $_POST['stock_sales_item_amt'][$i];

										//STOCK_ITEM
											if($selling_company_type == 3 && $receiving_company_type != 3 /*WHOLESALE=3, RETAIL=2*/)
											{
												$sql = "SELECT * FROM stock_items WHERE stock_item_id = '$purch_desc'";
												$result = mysqli_query($con,$sql);
												if(!empty($result) && mysqli_num_rows($result) > 0)
												{
													$row = mysqli_fetch_array($result);
													$retail_in_wholesale = $row['unit_id_retail_define'];
													if($retail_in_wholesale > 1)
													{
														$p_qty = $retail_in_wholesale * $purch_qty;
														$p_price = $purch_price / $retail_in_wholesale;
													}
													else
													{
														$p_qty = $purch_qty;
														$p_price = $purch_price;
													};
												}
												else
												{
													$p_qty = $purch_qty;
													$p_price = $purch_price;
												};
											}
											else
											{
												$p_qty = $purch_qty;
												$p_price = $purch_price;
											};

										$purch_selling_price = 0;
										$purch_batch = '';
										$purch_expiry_date = '';
										$purch_cat_id = 2;
										$selling_price = 0;
										$selling_price_branch = 0;

										$query = "INSERT INTO `purchase_items`(`company_id`, `sending_company_id`, `purchase_id`, `item_id`, 
										`warehouse_id`, `date`, `price`, `amount_pushed`, `batch`, `expiry_date`, `qty_pushed`, `branch_id`, 
										`sending_branch_id`, `created_by`, `created_datetime`, `stock_sales_id`, `stock_req_id`) 
										VALUES ('$buying_branch',
										'$company_id','$purchase_id','$purch_desc','$receiving_warehouse','$date', '$p_price',
										'$purch_amt','$purch_batch','$purch_expiry_date','$p_qty','$receiving_branch_id','$branch_id',
										'$user_id',NOW(),'$stock_sales_id','$stock_req_id')";
										mysqli_query($con, $query);
									}
								}
							};
						};
					};
			};

		}

		function search_stock_sales_by_name()
