		function stock_sales_pending_prescription()
		{
			global $con;
			$company_id = $_SESSION['company_id'];
			$value = "";

			$value .= '<table table class="table table-hover table-bordered table-sm" width="100%" cellspacing="0" style="font-size: 14px" id="stock_sales_pending_prescription_table">
