						<th class="action-td">Date</th>
						<th class="action-td">Age</th>
						<th>Origin</th>
						<th class="action-td">Pending Items</th>
						<th class="action-td">Action</th>
					</tr>
				<thead>
				<tbody>';

					$sql="SELECT a.*, p.firstName, p.lastName FROM attendance a JOIN patients p ON 
					a.patient_id=p.patient_id WHERE a.dispensing_company = '$company_id' ORDER BY 
					a.attend_id ASC";
					$result = mysqli_query($con, $sql);
					if(!empty($result) && mysqli_num_rows($result) > 0)
					{
						while($row = mysqli_fetch_array($result))
						{
							$i = 0;
							$attend_id = $row['attend_id'];
							$patient_id = $row['patient_id'];
							$company_id = $row['company_id'];

							$sql_co="SELECT trading_name FROM company WHERE company_id = '$company_id'";
							$result_co = mysqli_query($con,$sql_co);
							if(!empty($result_co) && mysqli_num_rows($result_co) > 0)
							{
								while($row_co = mysqli_fetch_array($result_co))
								{
									$trading_name = $row_co['trading_name'];
								};
							}
							else
							{
								$trading_name = 'Not Specified';
							};

							$total_qty_presc = 0;
							$sql_dl = "SELECT d.*, s.stock_item FROM drug_list d JOIN stock_items s ON d.drug_id=s.stock_item_id 
							WHERE d.attend_id = '$attend_id'";
							$result_dl = mysqli_query($con,$sql_dl);
							if(!empty($result_dl) && mysqli_num_rows($result_dl) > 0)
							{
								while($row_dl = mysqli_fetch_array($result_dl))
								{
									$drug_list_id = $row_dl['drug_list_id'];
									$qty_presc = $row_dl['qty_presc'];
									$stock_item = $row_dl['stock_item'];

									//FROM DISPENSE
										$sql_ddl="SELECT SUM(qty) AS qty_issued FROM drug_dispense_list WHERE 
										drug_list_id = '$drug_list_id' GROUP BY drug_list_id";
										$result_ddl = mysqli_query($con,$sql_ddl);
										if(!empty($result_ddl) && mysqli_num_rows($result_ddl) > 0)
										{
											while($row_ddl = mysqli_fetch_array($result_ddl))
											{
												$qty_issued_ddl = $row_ddl['qty_issued'];
											};
										}
										else
										{
											$qty_issued_ddl = 0;
										};

									//FROM SALES
										$sql_ssi = "SELECT SUM(qty) AS qty_issued FROM stock_sales_items WHERE 
										drug_list_id = '$drug_list_id' GROUP BY drug_list_id";
										$result_ssi = mysqli_query($con,$sql_ssi);
										if(!empty($result_ssi) && mysqli_num_rows($result_ssi) > 0)
										{
											while($row_ssi = mysqli_fetch_array($result_ssi))
											{
												$qty_issued_ssi = $row_ssi['qty_issued'];
											};
										}
										else
										{
											$qty_issued_ssi = 0;
										};

									$qty_issued = $qty_issued_ddl + $qty_issued_ssi;
									$qty = $qty_presc - $qty_issued;

									if($qty > 0)
									{
										$i++;
									}
								};

								if($i > 0)
								{
									$value .='<tr>
										<td>'.$row['firstName'].' '.$row['lastName'].'</td>
										<td class="action-td">'.$row['date_admit'].'</td>
										<td class="action-td">'.$row['age'].'</td>
										<td>'.$trading_name.'</td>
										<td class="action-td">'.$i.'</td>
										<td class="action-td">
                                            <a href="#" id="btn_dispense_stock_sales" data-attend_id="'.$attend_id.'">Dispense</a>
										</td>
									</tr>';
								}
								/*else
								{
									$value .='<tr>
										<td colspan="6">No Pending Prescriptions</td>
									</tr>';
								};*/
							};
						};
					};

				$value .= '</tbody>
			</table>';
			
			echo $value;
		}
		
