		function stock_sales_invoice_item_search()
		{
			global $con;
			$search = $_POST['search'];
			$company_id = $_SESSION['company_id'];
			$warehouse_id = $_POST['warehouse'];
			$branch_id = $_SESSION['branch_id'];
			$user_id = $_SESSION['user_id'];
			$start_date = date('2000-01-01');
			$end_date = date('Y-m-d');
			$value = "";
			$i = 1;

            $query = "SELECT d.stock_item_id, d.stock_item, d.price_cash, d.maintain_batch, d.block_negative, 
			p.price FROM stock_items d JOIN price_list p ON d.stock_item_id = p.stock_item_id AND p.company_id='$company_id'
			WHERE d.stock_item LIKE '%".$search."%' ORDER BY d.stock_item ASC LIMIT 20";
           	$query_run = mysqli_query($con, $query);
                
			echo'<table class="table table-hover table-bordered table-sm" id="stock_salesTable" width="100%" cellspacing="0">
			   	<thead>
					<tr>
						<th>Item Description</th>
						<th class = "action-td">Batch</th>
						<th class = "action-td">Qty</th>
						<th class = "action-td">Price</th>
						<th class = "action-td">Store Qty</th>
					</tr>
				</thead>
				<tbody class="pv-table-body">';
	
				if (mysqli_num_rows($query_run) > 0)
				{
					while($row = mysqli_fetch_assoc($query_run))
					{
						$stock_item_id = $row['stock_item_id'];
						if(isset($row['price']) && $row['price'] > 0)
						{
							$price = $row['price'];
						}
						else
						{
							$price = $row['price_cash'];
						};
						
						$query_bal = "SELECT item_id, SUM(ob) AS ob, SUM(qty_in) AS qty_in, SUM(qty_out) AS qty_out FROM
						(SELECT stock_item_id  AS item_id, 0 AS ob, 0 AS qty_out, qty AS qty_in FROM stock_purchase_items 
						WHERE date BETWEEN '$start_date' AND '$end_date' AND warehouse_id = '$warehouse_id' AND stock_item_id = '$stock_item_id'
						UNION ALL SELECT item_id AS item_id, 0 AS ob,  0 AS qty_out, qty AS qty_in FROM purchase_items 
						WHERE item_id='$stock_item_id' AND date BETWEEN '$start_date' AND '$end_date' AND warehouse_id ='$warehouse_id'
						UNION ALL SELECT drug_id AS item_id, 0 AS ob,  0 AS qty_out, qty AS qty_in FROM drug_patient_returns 
						WHERE drug_id='$stock_item_id' AND date BETWEEN '$start_date' AND '$end_date' AND warehouse_id ='$warehouse_id'
						UNION ALL SELECT drug_id AS item_id, 0 AS ob,  qty AS qty_out, 0 AS qty_in FROM drug_dispense_list 
						WHERE drug_id='$stock_item_id' AND date BETWEEN '$start_date' AND '$end_date' AND warehouse_id ='$warehouse_id'
						UNION ALL SELECT stock_item_id AS item_id, 0 AS ob,  qty AS qty_out, 0 AS qty_in FROM stock_sales_items 
						WHERE date BETWEEN '$start_date' AND '$end_date' AND warehouse_id = '$warehouse_id' AND stock_item_id = '$stock_item_id'
						UNION ALL SELECT stock_item_id AS item_id, 0 AS ob,  qty_out AS qty_out, 0 AS qty_in FROM stock_adjustment_items 
						WHERE date BETWEEN '$start_date' AND '$end_date' AND warehouse_id = '$warehouse_id' AND stock_item_id = '$stock_item_id'
						UNION ALL SELECT stock_item_id AS item_id, 0 AS ob,  qty_transferred AS qty_out, 0 AS qty_in FROM stock_transfer_items 
						WHERE stock_item_id BETWEEN '$start_date' AND '$end_date' AND warehouse_id = '$warehouse_id' AND stock_item_id = '$stock_item_id'
						UNION ALL SELECT stock_item_id AS item_id, 0 AS ob,  0 AS qty_out, qty_in AS qty_in FROM stock_adjustment_items 
						WHERE date BETWEEN '$start_date' AND '$end_date' AND warehouse_id = '$warehouse_id' AND stock_item_id = '$stock_item_id'
						UNION ALL SELECT stock_item_id AS item_id, 0 AS ob,  0 AS qty_out, qty_received AS qty_in FROM stock_transfer_items 
						WHERE date_trans BETWEEN '$start_date' AND '$end_date' AND warehouse_id = '$warehouse_id' AND stock_item_id = '$stock_item_id') AS c GROUP BY item_id";

           				$query_run_bal = mysqli_query($con, $query_bal);
	
						if (mysqli_num_rows($query_run_bal) > 0)
						{
							$row_bal = mysqli_fetch_assoc($query_run_bal);
							$balance = $row_bal['ob']+$row_bal['qty_in']-$row_bal['qty_out'];
						}
						else
						{
							$balance = 0;
						};

						echo'<tr id="'.$i.'">
							<td>
								<a href="#" id="btn_add_stock_sales_invoice_item" 
									data-id="'.$row['stock_item_id'].'"
									data-id1="'.$row['stock_item'].'"
									data-id2="'.$price.'"
									data-id3="'.$row['maintain_batch'].'"
									data-id4="'.$row['block_negative'].'"
								>
								<strong>'.$row['stock_item'].'</strong></a>
							</td>
							<td class = "action-td">
								<input type="text" class="form-control text-center" name="item_search_batch" id="item_search_batch'.$i.'">
							</td>
							<td class = "action-td">
								<input type="text" class="form-control text-center" name="item_search_qty" id="item_search_qty'.$i.'">
							</td>
							<td>
								<input type="text" class="form-control text-right" name="item_search_price" id="item_search_price'.$i.'" value="'.$price.'" hidden="true">
								<input type="text" class="form-control text-right" name="item_search_priceD" id="item_search_priceD'.$i.'" value="'.$price.'" disabled="true">
							</td>
							<td class = "amt-td">
								<input type="text" class="form-control text-right" name="item_search_balance" id="item_search_balance'.$i.'" value="'.$balance.'" disabled="true">
							</td>
						</tr>';
						$i++;
					};
				}
				else
				{
					echo'No Stock Item Not Found';
				};
			   echo'</tbody>
			</table>';
		}
		
		function stock_sales_invoice_item_search_save()
		{
			global $con;
			$stock_item_id = $_POST['stock_item_id'];
			$stock_item = $_POST['stock_item'];
			//$qty = $_POST['qty'];
			//$qty_billed = $_POST['qty_billed'];
			//$original_price = $_POST['price'];
			//$amount = $_POST['amount'];
			
			if(isset($_POST['qty']) && $_POST['qty'] > 0){$qty = $_POST['qty'];}else{$qty = 0;};
			if(isset($_POST['qty_billed']) && $_POST['qty_billed'] > 0){$qty_billed = $_POST['qty_billed'];}else{$qty_billed = 0;};
			if(isset($_POST['disc_perc']) && $_POST['disc_perc'] > 0){$disc_perc = $_POST['disc_perc'];}else{$disc_perc = 0;};
			if(isset($_POST['disc_amount']) && $_POST['disc_amount'] > 0){$disc_amount = $_POST['disc_amount'];}else{$disc_amount = 0;};
			if(isset($_POST['price']) && $_POST['price'] > 0){$original_price = $_POST['price'];}else{$original_price = 0;};
			if(isset($_POST['amount']) && $_POST['amount'] > 0){$amount = $_POST['amount'];}else{$amount = 0;};
			$count = $_POST['count'];
			$batch_no = $_POST['batch_no'];
			if(isset($insurance) && $insurance > 0)
			{
				$insurance = $_POST['insurance'];
				$sql="SELECT * FROM ledgers WHERE ledger_id = '$insurance'";
				$result = mysqli_query($con,$sql);
				if(!empty($result) && mysqli_num_rows($result) > 0)
				{
					$row = mysqli_fetch_array($result);
					if(isset($row['mark_up']))
					{
						if($row['mark_up'] >= 1)
						{
							$mark_up = $row['mark_up']/100;
						}
						else
						{
							$mark_up = $row['mark_up'];
						};
					}
					else
					{
						$mark_up = 0;
					};
				}
				else
				{
					$mark_up = 0;
				};
			}
			else
			{
				$mark_up = 0;
			};
			$price = $original_price + ($mark_up * $original_price);
			$amount = $qty * $price;

			$price_f = number_format($price, 2, '.', ',');
			$amount_f = number_format($amount, 2, '.', ',');
			$disc_amount_f = number_format($disc_amount, 2, '.', ',');
			$count++;

			echo '<tr id="item_list'.$count.'">
				<input type="hidden" name="stock_sales_invoice_item_id[]" id="stock_sales_invoice_item_id'.$count.'" value="'.$stock_item_id.'">
				<input type="hidden" name="stock_sales_invoice_item_qty[]" id="stock_sales_invoice_item_qty'.$count.'" value="'.$qty.'">
				<input type="hidden" name="stock_sales_invoice_item_qty_billed[]" id="stock_sales_invoice_item_qty_billed'.$count.'" value="'.$qty_billed.'">
				<input type="hidden" name="stock_sales_invoice_item_disc_perc[]" id="stock_sales_invoice_item_disc_perc'.$count.'" value="'.$disc_perc.'">
				<input type="hidden" class="stock_sales_invoice_item_disc_amount" name="stock_sales_invoice_item_disc_amount[]" id="stock_sales_invoice_item_disc_amount'.$count.'" value="'.$disc_amount.'">
				<input type="hidden" name="stock_sales_invoice_item_price[]" id="stock_sales_invoice_item_price'.$count.'" value="'.$price.'">
				<input type="hidden" name="stock_sales_invoice_item_batch_no[]" id="stock_sales_invoice_item_batch_no'.$count.'" value="'.$batch_no.'">
				<input type="hidden" class="stock_sales_invoice_item_amount" name="stock_sales_invoice_item_amount[]" id="stock_sales_invoice_item_amount'.$count.'" value="'.$amount.'">
				<td>'.$stock_item.'</td>
				<td class = "action-td">'.$qty.'</td>
				<td class = "amt-td">'.$price_f.'</td>
				<td class = "amt-td">'.$amount_f.'</td>
				<td class = "amt-td">'.$disc_amount_f.'</td>
				<td class = "action-td">
					<!--<a href="#" data-toggle="" id="label_stock_sales_invoice">Label</a>
					| 
					<a href="#" data-toggle="" id="mur_stock_sales_invoice">MUR</a>
					|-->
					<a href="#" data-toggle="" id="delete_stock_sales_invoice_item" data-id="'.$count.'">Delete</a>
				</td>
			</tr>';
			
		}

