		function stock_sales_invoice_add_qty()
		{
			global $con;
			$stock_item_id = $_POST['stock_item_id'];
			$maintain_batch = $_POST['maintain_batch'];
			$block_negative = $_POST['block_negative'];
			$warehouse_id = $_SESSION['warehouse_id'];
			$start_date = date('2000-01-01');
			$end_date = date('Y-m-d');
			$data = array();
			$value = "";
			$batch_list = "";
			$i = 0;

			$select = '<label for="batch_qty_batch_no">Batch/Lot Number</label>
			<select class="form-control bg-light text-center" name="batch_qty_batch_no" id="batch_qty_batch_no">
				<option value="0" data-id="0">Please select</option>';

			$query = "SELECT * FROM purchase_items WHERE item_id = '$stock_item_id' AND 
			warehouse_id = '$warehouse_id' GROUP BY batch";
			$query_run = mysqli_query($con, $query);

			$value .= '<table table class="table table-hover table-bordered table-sm" width="100%" cellspacing="0" style="font-size: 14px" id="stock_sales_invoice_batch_qty_batch_expiry_table">
				<tr style="background:#F3F1F1; color:black">
					<th colspan="4" class="action-td">BATCH LIST</th>
				</tr>
				<tr>
					<th width="40%" class="action-td">Batch/Lot Number</th>
					<th width="20%" class="action-td">Batch Qty</th>
					<th width="20%" class="action-td">Expiry Date</th>
					<th width="20%" class="action-td">Days to Expire</th>
				</tr>';
	
				if (!empty($query_run) && mysqli_num_rows($query_run) > 0)
				{
					while($row = mysqli_fetch_assoc($query_run))
					{
						$i++;
						$batch = $row['batch'];

						$query_bal = "SELECT item_id, SUM(ob) AS ob, SUM(qty_in) AS qty_in, SUM(qty_out) AS qty_out FROM
						(SELECT item_id  AS item_id, warehouse_id, 0 AS ob, 0 AS qty_out, qty AS qty_in FROM purchase_items 
						WHERE date BETWEEN '$start_date' AND '$end_date' AND warehouse_id = '$warehouse_id' AND item_id = '$stock_item_id' AND batch = '$batch'
						UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 AS ob,  qty AS qty_out, 0 AS qty_in FROM stock_sales_items 
						WHERE date BETWEEN '$start_date' AND '$end_date' AND warehouse_id = '$warehouse_id' AND stock_item_id = '$stock_item_id' AND batch = '$batch'
						UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 AS ob,  qty_out AS qty_out, 0 AS qty_in FROM stock_adjustment_items 
						WHERE date BETWEEN '$start_date' AND '$end_date' AND warehouse_id = '$warehouse_id' AND stock_item_id = '$stock_item_id' AND batch_no = '$batch'
						UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 AS ob,  qty_transferred AS qty_out, 0 AS qty_in FROM stock_transfer_items 
						WHERE date_trans BETWEEN '$start_date' AND '$end_date' AND warehouse_id = '$warehouse_id' AND stock_item_id = '$stock_item_id' AND batch_no = '$batch'
						UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 AS ob,  0 AS qty_out, qty_in AS qty_in FROM stock_adjustment_items
						WHERE date BETWEEN '$start_date' AND '$end_date' AND warehouse_id = '$warehouse_id' AND stock_item_id = '$stock_item_id' AND batch_no = '$batch'
						UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 AS ob,  0 AS qty_out, qty_received AS qty_in FROM stock_transfer_items
						WHERE date_trans BETWEEN '$start_date' AND '$end_date' AND warehouse_id = '$warehouse_id' AND stock_item_id = '$stock_item_id' AND batch_no = '$batch') AS c GROUP BY item_id";

           				$query_run_bal = mysqli_query($con, $query_bal);
	
						if (mysqli_num_rows($query_run_bal) > 0)
						{
							$row_bal = mysqli_fetch_assoc($query_run_bal);
							$balance = $row_bal['ob']+$row_bal['qty_in']-$row_bal['qty_out'];
						}
						else
						{
							$balance = 0;
						};

						if($balance > 0)
						{	
							$expiry = $row['expiry_date'];
							$today = date('Y-m-d');
							$select .= '<option value="'.$batch.'" data-id="'.$balance.'">'.$batch.'</option>';

							$startTimeStamp = strtotime($today);
							$endTimeStamp = strtotime($expiry);
							$timeDiff = abs($endTimeStamp - $startTimeStamp);
							$numberDays = $timeDiff/86400;
							$numberDays = intval($numberDays);

							//<tr>
								if($numberDays < 31)
								{
									$value .='<tr id="'.$i.'" style="background:salmon; color:black">';
								}
								else if($numberDays > 30 && $numberDays < 91)
								{
									$value .='<tr id="'.$i.'" style="background:lightyellow; color:black">';
								}
								else if($numberDays > 90)
								{
									$value .='<tr id="'.$i.'" style="color:black">';
								};

								$value .='<td class="action-td">'.$batch.'</td>
								<td class="action-td">'.$balance.'</td>
								<td class="action-td">'.$row['expiry_date'].'</td>
								<td class="action-td">'.$numberDays.'</td>
							</tr>';
						};
					};
				}
				else
				{
					$value .= '<tr><td colspan="4">No Batches Found</td></tr>';
				};
			   	$value .= '</tbody>
			</table>';

				$select .= '</select>';
					if($maintain_batch == 'Yes' && mysqli_num_rows($query_run) > 0)
					{
						$batch_list = $select;
					}
					else
					{
						$batch_list = '<label for="batch_qty_batch_no">Batch/Lot Number</label>
						<input type="text" name="batch_qty_batch_no" class="form-control bg-light text-center" id="batch_qty_batch_no">';
					};

			array_push($data, $value, $batch_list);
			echo json_encode($data);
		}

