				$query_run_lab_performed = mysqli_query($con, $query_lab_performed);
				if (mysqli_num_rows($query_run_lab_performed) > 0)
				{
					array_push($Lab_Data, 
						'performed',
						$_SESSION['user_type']
					);
				}
				else
				{
					array_push($Lab_Data, 
						'empty',
						$_SESSION['user_type']
					);
				};
			}

