		function sales_returns_save()
		{
			global $con;
			$stock_sales_id = $_POST['stock_sales_returns_stock_sales_id'];
			$stock_sales_return_id = $_POST['stock_sales_return_id'];
			$debit_ledger = $_POST['stock_sales_returns_debit_ledger'];
			$credit_ledger = $_POST['stock_sales_returns_credit_ledger'];
			$reference = $_POST['stock_sales_returns_reference'];
			$date = $_POST['stock_sales_returns_date'];
			$amount = $_POST['stock_sales_returns_amount'];
			$reason = $_POST['stock_sales_returns_reason'];
			$sent_by = $_POST['stock_sales_returns_sent_by'];
			$received_by = $_POST['stock_sales_returns_received_by'];
			$warehouse = $_POST['stock_sales_returns_warehouse'];
			$company_id = $_SESSION['company_id'];
			$branch_id = $_SESSION['branch_id'];
			$user_id = $_SESSION['user_id'];

			$query = "INSERT INTO `stock_sales_return`(`company_id`,`date`,`ledger_debit`,`ledger_credit`,
			`amount`,`reference_no`,`supplied_by`,`received_by`,`narration`,`warehouse_id`,`created_by`,
			`created_datetime`,`branch_id`) VALUES ('$company_id','$date','$debit_ledger','$credit_ledger',
			'$amount','$reference','$sent_by','$received_by','$reason','$warehouse','$user_id',NOW(),
			'$branch_id')";
			$query_run = mysqli_query($con, $query);

			if($query_run) 
			{
				//POST TRANSACTION
					$query_sl = "SELECT * FROM stock_sales_return ORDER BY stock_sales_return_id DESC";
					$result_sl = mysqli_query($con, $query_sl);
					$row_sl = mysqli_fetch_assoc($result_sl);
					$stock_sales_return_id = $row_sl['stock_sales_return_id'];

					$query_dr = "INSERT INTO `transactions`(`company_id`,`stock_sales_return_id`,`ledger_id`, 
					`ledger_id_contra`, `date`, `amt`, `amt_debit`, `narration`,`branch_id`, `created_by`, 
