		function purchase_returns_save()
		{
			global $con;
			$purchase_id = $_POST['purchase_returns_purchase_id'];
			$debit_ledger = $_POST['purchase_returns_debit_ledger'];
			$credit_ledger = $_POST['purchase_returns_credit_ledger'];
			$warehouse = (int)$_POST['purchase_returns_warehouse'];
			$date = $_POST['purchase_returns_date'];
			$reason = $_POST['purchase_returns_reason'];
			$reference = $_POST['purchase_returns_reference'];
			$sent_by = $_POST['purchase_returns_sent_by'];
			$received_by = $_POST['purchase_returns_received_by'];
			$amount = $_POST['purchase_returns_amount'];
			$company_id = $_SESSION['company_id'];
			$branch_id = $_SESSION['branch_id'];
			$user_id = $_SESSION['user_id'];

			$query = "INSERT INTO `purchase_return`(`purchase_id`,`ledger_debit`,`ledger_credit`,`amount`,
			`narration`,`date`,`warehouse_id`,`company_id`,`branch_id`,`sent_by`,`received_by`,`reference_no`,
			`created_by`,`created_datetime`) VALUES ('$purchase_id','$debit_ledger','$credit_ledger','$amount',
			'$reason','$date','$warehouse','$company_id','$branch_id','$sent_by','$received_by','$reference',
			'$user_id',NOW())";
			$query_run = mysqli_query($con, $query);

			if($query_run) 
			{
				//POST TRANSACTION
					$query_sl = "SELECT * FROM purchase_return ORDER BY purchase_return_id DESC";
					$result_sl = mysqli_query($con, $query_sl);
					$row_sl = mysqli_fetch_assoc($result_sl);
					$purchase_return_id = $row_sl['purchase_return_id'];

					$query_dr = "INSERT INTO `transactions`(`company_id`,`purchase_return_id`,`ledger_id`, 
					`ledger_id_contra`, `date`, `amt`, `amt_debit`, `narration`,`branch_id`, `created_by`, 
					`created_datetime`) VALUES ('$company_id','$purchase_return_id','$debit_ledger','$credit_ledger',
					'$date','$amount','$amount','$reason','$branch_id','$user_id', NOW())";
					mysqli_query($con, $query_dr);

					$query_cr = "INSERT INTO `transactions`(`company_id`,`purchase_return_id`,`ledger_id`, 
					`ledger_id_contra`, `date`, `amt`, `amt_credit`, `narration`, `branch_id`, `created_by`, 
					`created_datetime`) VALUES ('$company_id','$purchase_return_id','$credit_ledger','$debit_ledger',
					'$date','$amount','$amount','$reason','$branch_id','$user_id', NOW())";
					mysqli_query($con, $query_cr);

				//PURCHASE_ITEM_LIST
					$number_as = count($_POST["purchase_return_item_id"]);
					if($number_as > 0)  
					{  
						for($i = 0; $i < $number_as; $i++)  
						{  
							if(trim($_POST["purchase_return_item_id"][$i] > 0) && trim($_POST["purchase_returns_qty"][$i] > 0))  
