			`amount`='$amount',`narration`='$reason',`date`='$date',`sent_by`='$sent_by',`received_by`='$received_by',
			`reference_no`='$reference',`warehouse_id`='$warehouse',`altered_by`='$user_id',`altered_datetime`=NOW() WHERE `purchase_return_id`='$purchase_return_id'";
			$query_run = mysqli_query($con, $query);

			if($query_run) 
			{
				//POST TRANSACTION
					$query = "DELETE FROM transactions WHERE purchase_return_id='$purchase_return_id'";
					mysqli_query($con,$query);
					$query = "DELETE FROM purchase_return_items WHERE purchase_return_id='$purchase_return_id'";
					mysqli_query($con,$query);

					$query_dr = "INSERT INTO `transactions`(`company_id`,`purchase_return_id`,`ledger_id`, 
					`ledger_id_contra`, `date`, `amt`, `amt_debit`, `narration`,`branch_id`, `created_by`, 
					`created_datetime`) VALUES ('$company_id','$purchase_return_id','$debit_ledger','$credit_ledger',
					'$date','$amount','$amount','$reason','$branch_id','$user_id', NOW())";
					mysqli_query($con, $query_dr);

					$query_cr = "INSERT INTO `transactions`(`company_id`,`purchase_return_id`,`ledger_id`, 
					`ledger_id_contra`, `date`, `amt`, `amt_credit`, `narration`, `branch_id`, `created_by`, 
					`created_datetime`) VALUES ('$company_id','$purchase_return_id','$credit_ledger','$debit_ledger',
					'$date','$amount','$amount','$reason','$branch_id','$user_id', NOW())";
					mysqli_query($con, $query_cr);

				//PURCHASE_ITEM_LIST
					$number_as = count($_POST["purchase_return_item_id"]);
					if($number_as > 0)  
					{  
						for($i=0; $i<$number_as; $i++)  
						{  
							if(trim($_POST["purchase_return_item_id"][$i] > 0) && trim($_POST["purchase_returns_qty"][$i] > 0))  
							{
								$item_id = $_POST['purchase_return_item_id'][$i];
								$qty = $_POST['purchase_returns_qty'][$i];
								$price = $_POST['purchase_returns_price'][$i];
								$amt = $_POST['purchase_returns_amount'][$i];
								$batch = '';
								$expiry_date = '';
								
								$query = "INSERT INTO `purchase_return_items`
								(`company_id`, `purchase_return_id`, `item_id`, `warehouse_id`, `date`, `price`, `amount`, 
								`batch`, `expiry_date`, `qty`, `branch_id`) VALUES 
								('$company_id','$purchase_return_id','$purch_desc','$warehouse','$date',
								'$price','$amt','$batch','$expiry_date','$qty','$branch_id')";
								mysqli_query($con, $query);
