			$query = "INSERT INTO `sales_order`(
			`company_id`, `date`, `customer_name`, `telephone`, `status`) 
			VALUES ('$branch', '$date', '$name', '$telephone', 'pending')";
			$query_run = mysqli_query($con, $query);

			if($query_run) 
			{
				//POST TRANSACTION
					$query = "SELECT * FROM sales_order ORDER BY sales_order_id DESC";
					$result = mysqli_query($con,$query);
