		function sales_order_conversion_save()
		{
			global $con;
			$sales_order_id = $_POST['sales_order_id'];
			$warehouse_id = $_POST['sales_order_from'];
			$debit_ledger = $_POST['sales_order_ledger'];
			$credit_ledger = 5;
			$date = $_POST['sales_order_date'];
			$amount = $_POST['sales_order_amount'];
			$discount = $_POST['sales_order_discount_amount'];
			$requested_by = $_POST['sales_order_requested_by'];
			$telephone = $_POST['sales_order_requested_telephone'];
			$narration = $_POST['sales_order_narration'];

			$company_id = $_SESSION['company_id'];
			$branch_id = $_SESSION['branch_id'];
			$user_id = $_SESSION['user_id'];
			$full_name = $_SESSION['full_name'];

			$query = "SELECT sno FROM stock_sales WHERE company_id = '$company_id' 
			AND branch_id = '$branch_id' ORDER BY sno DESC";
			$result = mysqli_query($con,$query);
			if (mysqli_num_rows($result) > 0)
			{
				$row = mysqli_fetch_assoc($result);
				$sno = $row['sno'] + 1;
			}
			else
			{
				$sno = 1;
			};

			$query = "INSERT INTO `stock_sales`(
			`company_id`,`date`, `ledger_credit`, `amount`, `reference_no`, `warehouse_id`,
			`supplied_by`, `received_by`, `narration`, `sno`, `branch_id`, `customer_id`, `age`, 
			`id_number`,`total_payment_option`, `total_invoice_value`, 
			`discount`, `net_amount`,`created_by`, `created_datetime`, `insurance_id`, `type`) 
			VALUES ('$company_id','$date','$sales_credit','$amount','$sno','$warehouse_id',
			'$full_name','$requested_by','$sales_narration','$sno','$branch_id','$customer_id',
			'$customer_age','$customer_id_number','$amount',
			'$sub_total','$discount','$net_amount','$user_id',NOW(),'$insurance','$sales_type')";
			$query_run = mysqli_query($con, $query);
			
			if ($query_run) 
			{
				$query = "SELECT * FROM stock_sales ORDER BY stock_sales_id DESC";
				$result = mysqli_query($con,$query);
				$row = mysqli_fetch_assoc($result);
				$stock_sales_id = $row['stock_sales_id'];
				$_SESSION['stock_sales_id'] = $stock_sales_id;
				$_SESSION['customer_name'] = $customer_name;

				$ledger_as = count($_POST["payment_option_ledger_id"]);  
				if($ledger_as > 0)  
				{  
					for($i=0; $i < $ledger_as; $i++)  
					{  
						if(trim($_POST["payment_option_ledger_id"][$i] != '') && trim($_POST["payment_option_ledger_id"][$i] != 0))  
						{  
							$sales_debit = $_POST['payment_option_ledger_id'][$i];
							$sales_amount = $_POST['payment_option_ledger_amount'][$i];
							$query_dr = "INSERT INTO `transactions`(
							`company_id`,`branch_id`,`stock_sales_id`,`ledger_id`, `ledger_id_contra`, `date`, `amt`, 
							`amt_debit`, `narration`,`created_by`, `created_datetime`) VALUES (
							'$company_id','$branch_id','$stock_sales_id','$sales_debit','$sales_credit','$date',
							'$sales_amount','$sales_amount','$sales_narration','$user_id',NOW())";
							mysqli_query($con, $query_dr);
		
							$query_cr = "INSERT INTO `transactions`(
							`company_id`,`branch_id`,`stock_sales_id`,`ledger_id`, `ledger_id_contra`, `date`, `amt`, 
							`amt_credit`, `narration`,`created_by`, `created_datetime`) VALUES (
							'$company_id','$branch_id','$stock_sales_id','$sales_credit','$sales_debit','$date',
							'$sales_amount','$sales_amount','$sales_narration','$user_id',NOW())";
							mysqli_query($con, $query_cr);
						};
					};
				};

				$number_as = count($_POST["stock_sales_invoice_item_id"]);
				$_SESSION['no_of_items_sold'] = $number_as;
				if($number_as > 0)  
				{  
					for($i=0; $i<$number_as; $i++)  
					{  
						if(trim($_POST["stock_sales_invoice_item_id"][$i] != '') && trim($_POST["stock_sales_invoice_item_id"][$i] != 0))  
						{  
							$item_id = $_POST['stock_sales_invoice_item_id'][$i];
							$item_qty = $_POST['stock_sales_invoice_item_qty'][$i];
							$item_price = $_POST['stock_sales_invoice_item_price'][$i];
							$item_amount = $_POST['stock_sales_invoice_item_amount'][$i];
							$item_batch_no = $_POST['stock_sales_invoice_item_batch_no'][$i];
							$query = "INSERT INTO `stock_sales_items`
							(`company_id`,`branch_id`, `stock_sales_id`, `stock_item_id`, `warehouse_id`, `date`, `price`, `amount`, 
							`qty`,`created_by`, `created_datetime`,`batch`) VALUES 
							('$company_id','$branch_id','$stock_sales_id','$item_id','$warehouse_id','$date',
							'$item_price','$item_amount',
							'$item_qty','$user_id',NOW(),'$item_batch_no')";
							mysqli_query($con, $query);
						}; 
					};
				};
			}
		}

