				global $con;
				$warehouse = $_POST['stock_adjustment_zero_warehouse'];
				$date = $_POST['stock_adjustment_zero_date'];
				$start_date = date('2023-01-01');
				$end_date = $_POST['stock_adjustment_zero_date'];
				
