				$company_id = $_SESSION['company_id'];
				$branch_id = $_SESSION['branch_id'];
				$user_id = $_SESSION['user_id'];
				
				$query_stk_adj = "INSERT INTO `stock_adjustment`(`company_id`, `reference_no`, `date`, `narration`, `adjusted_by`, 
				`branch_id`, `created_by`, `created_datetime`) 
				VALUES ('$company_id','$stk_adj_ref_no','$stk_adj_date','$stk_adj_narration','$stk_adj_adjusted_by',
				'$branch_id','$user_id',NOW())";
				$query_run_stk_adj = mysqli_query($con, $query_stk_adj);
	
				if ($query_run_stk_adj) 
				{
					$query_select = "SELECT * FROM stock_adjustment ORDER BY stock_adj_id  DESC";
					$result_select = mysqli_query($con,$query_select);
					$row_select = mysqli_fetch_assoc($result_select);
					$stock_adj_id  = $row_select['stock_adj_id'];
	
					$query="SELECT item_id, SUM(ob) AS ob, SUM(qty_in) AS qty_in, SUM(qty_out) AS qty_out FROM
					(SELECT con_id AS item_id, warehouse_id, 0 - qty_issued AS ob,  0 AS qty_out, 0 AS qty_in FROM consumable_list 
					WHERE warehouse_id ='$warehouse' AND company_id = '$company_id' AND date < '$start_date'
					UNION ALL SELECT drug_id AS item_id, warehouse_id, qty - 0 AS ob,  0 AS qty_out, 0 AS qty_in FROM drug_patient_returns 
					WHERE warehouse_id ='$warehouse' AND company_id = '$company_id' AND date < '$start_date'
					UNION ALL SELECT drug_id AS item_id, warehouse_id, 0 - qty AS ob,  0 AS qty_out, 0 AS qty_in FROM drug_dispense_list 
					WHERE warehouse_id ='$warehouse' AND company_id = '$company_id' AND date < '$start_date'
					UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 - qty AS ob, 0 AS qty_out, 0 AS qty_in FROM stock_sales_items 
					WHERE warehouse_id ='$warehouse' AND company_id = '$company_id' AND date < '$start_date'
					UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 - qty_out AS ob,  0 AS qty_out, 0 AS qty_in FROM stock_adjustment_items 
					WHERE warehouse_id ='$warehouse' AND company_id = '$company_id' AND  date < '$start_date'
					UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 - qty_transferred AS ob,  0 AS qty_out, 0 AS qty_in FROM stock_transfer_items 
					WHERE warehouse_id ='$warehouse' AND company_id = '$company_id' AND date_trans < '$start_date'
					UNION ALL SELECT stock_item_id AS item_id, warehouse_id, qty_in - 0 AS ob,  0 AS qty_out, 0 AS qty_in FROM stock_adjustment_items 
					WHERE warehouse_id ='$warehouse' AND company_id = '$company_id' AND date < '$start_date'
					UNION ALL SELECT stock_item_id AS item_id, warehouse_id, qty_received - 0 AS ob,  0 AS qty_out, 0 AS qty_in FROM stock_transfer_items 
					WHERE warehouse_id ='$warehouse' AND company_id = '$company_id' AND date_trans < '$start_date'
					UNION ALL SELECT item_id AS item_id, warehouse_id, qty - 0 AS ob,  0 AS qty_out, 0 AS qty_in FROM purchase_items 
					WHERE warehouse_id ='$warehouse' AND company_id = '$company_id' AND date < '$start_date'
					UNION ALL SELECT stock_item_id AS item_id, warehouse_id, qty - 0 AS ob,  0 AS qty_out, 0 AS qty_in FROM stock_sales_return_items 
					WHERE warehouse_id ='$warehouse' AND company_id = '$company_id' AND date < '$start_date'
					UNION ALL SELECT item_id AS item_id, warehouse_id, 0 - qty AS ob,  0 AS qty_out, 0 AS qty_in FROM purchase_return_items 
					WHERE warehouse_id ='$warehouse' AND company_id = '$company_id' AND date < '$start_date'

					UNION ALL SELECT con_id AS item_id, warehouse_id, 0 AS ob,  qty_issued AS qty_out, 0 AS qty_in FROM consumable_list 
					WHERE warehouse_id ='$warehouse' AND company_id = '$company_id' AND date BETWEEN '$start_date' AND '$end_date'
					UNION ALL SELECT drug_id AS item_id, warehouse_id, 0 AS ob,  0 AS qty_out, qty AS qty_in FROM drug_patient_returns 
					WHERE warehouse_id ='$warehouse' AND company_id = '$company_id' AND date BETWEEN '$start_date' AND '$end_date'
					UNION ALL SELECT drug_id AS item_id, warehouse_id, 0 AS ob,  qty AS qty_out, 0 AS qty_in FROM drug_dispense_list 
					WHERE warehouse_id ='$warehouse' AND company_id = '$company_id' AND date BETWEEN '$start_date' AND '$end_date'
					UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 AS ob,  qty AS qty_out, 0 AS qty_in FROM stock_sales_items 
					WHERE warehouse_id ='$warehouse' AND company_id = '$company_id' AND date BETWEEN '$start_date' AND '$end_date'
					UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 AS ob,  qty_out AS qty_out, 0 AS qty_in FROM stock_adjustment_items 
					WHERE warehouse_id ='$warehouse' AND company_id = '$company_id' AND  date BETWEEN '$start_date' AND '$end_date'
					UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 AS ob,  qty_transferred AS qty_out, 0 AS qty_in FROM stock_transfer_items 
					WHERE warehouse_id ='$warehouse' AND company_id = '$company_id' AND date_trans BETWEEN '$start_date' AND '$end_date'
					UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 AS ob,  0 AS qty_out, qty_in AS qty_in FROM stock_adjustment_items 
					WHERE warehouse_id ='$warehouse' AND company_id = '$company_id' AND date BETWEEN '$start_date' AND '$end_date'
					UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 AS ob,  0 AS qty_out, qty_received AS qty_in FROM stock_transfer_items 
					WHERE warehouse_id ='$warehouse' AND company_id = '$company_id' AND date_trans BETWEEN '$start_date' AND '$end_date'
					UNION ALL SELECT item_id AS item_id, warehouse_id, 0 AS ob,  0 AS qty_out, qty AS qty_in FROM purchase_items 
					WHERE warehouse_id ='$warehouse' AND company_id = '$company_id' AND date BETWEEN '$start_date' AND '$end_date'
					UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 AS ob,  0 AS qty_out, qty AS qty_in FROM stock_sales_return_items 
					WHERE warehouse_id ='$warehouse' AND company_id = '$company_id' AND date BETWEEN '$start_date' AND '$end_date'
					UNION ALL SELECT item_id AS item_id, warehouse_id, 0 AS ob,  qty AS qty_out, 0 AS qty_in FROM purchase_return_items 
					WHERE warehouse_id ='$warehouse' AND company_id = '$company_id' AND date BETWEEN '$start_date' AND '$end_date') AS d GROUP BY item_id";

					$query_run = mysqli_query($con, $query);
					if (mysqli_num_rows($query_run) > 0)
					{
						while($row = mysqli_fetch_assoc($query_run))
						{
							$balance = $row['ob'] + $row['qty_in'] - $row['qty_out'];
							
							if($balance > 0)
							{
								$qty_in = 0;
								$qty_out = $balance;
							}
							else
							{
								$qty_in = abs($balance);
								$qty_out = 0;
							};
							$stk_adj_qty_in = $qty_in;
							$stk_adj_qty_out = $qty_out;
	
							$stk_adj_item_id = $row['item_id'];
							$stk_adj_date = $date;
							$stock_adj_wh = $warehouse;
							$stock_adj_batch_no = 'N/A';
							$query_stk_adj_items = "INSERT INTO `stock_adjustment_items`
							(`company_id`,`stock_adj_id`, `date`, `stock_item_id`, `warehouse_id`, `batch_no`, `qty_in`, 
							`qty_out`,`branch_id`, `created_by`, `created_datetime`) VALUES ('$company_id','$stock_adj_id',
							'$stk_adj_date','$stk_adj_item_id','$stock_adj_wh','$stock_adj_batch_no',
							'$stk_adj_qty_in','$stk_adj_qty_out','$branch_id','$user_id',NOW())";
							mysqli_query($con, $query_stk_adj_items);
						};
					};
				};
			}

	//STOCK TAKE
		function import_stock_adjustment()
		{
			global $con;
			if (isset($_POST['stock_adjustment_import_import_btn'])) 
			{
				$store = $_POST['stock_adjustment_import_store'];
				$date = $_POST['stock_adjustment_import_date'];
				$company_id = $_SESSION['company_id'];
				$branch_id = $_SESSION['branch_id'];
				$user_id = $_SESSION['user_id'];
				$user = $_SESSION['full_name'];
				$reference = 'ST/'.$store.'/'.$date;
				$narration = 'STOCK TAKE ON '.$date;

				$csvMimes = array('text/x-comma-separated-values', 'text/comma-separated-values', 
				'application/octet-stream', 'application/vnd.ms-excel', 'application/x-csv', 
				'text/x-csv', 'text/csv', 'application/csv', 'application/excel', 'application/vnd.msexcel', 
				'text/plain');

				if (!empty($_FILES['stock_adjustment_import_file']['name']) && in_array($_FILES['stock_adjustment_import_file']['type'], $csvMimes)) 
				{
					if (is_uploaded_file($_FILES['stock_adjustment_import_file']['tmp_name'])) 
					{
						$csvFile = fopen($_FILES['stock_adjustment_import_file']['tmp_name'], 'r');
						fgetcsv($csvFile);
						
						$query = "INSERT INTO `stock_adjustment`(`company_id`, `reference_no`, `date`, `warehouse_id`, 
						`narration`, `adjusted_by`, `created_by`, `created_datetime`, `branch_id`) 
						VALUES ('$company_id','$reference','$date','$store','$narration','$user',
						'$user_id',NOW(),'$branch_id')";
						$query_run = mysqli_query($con, $query);

						if ($query_run) 
						{
							$query = "SELECT * FROM stock_adjustment ORDER BY stock_adj_id  DESC";
							$result = mysqli_query($con,$query);
							$row = mysqli_fetch_assoc($result);
							$stock_adj_id  = $row['stock_adj_id'];

							while (($line = fgetcsv($csvFile)) !== false) 
							{
								$item_number   = $line[0];
								$item_name  = $line[1];
								$qty_in  = $line[3];
								$batch_no  = $line[4];
								$exp_date  = $line[5];
								$expiry_date = date("Y-m-j", strtotime($exp_date));

								if($qty_in > 0)
								{
									$query_stk = "SELECT * FROM stock_items WHERE code='$item_number'";
									$result_stk = mysqli_query($con,$query_stk);
									$row_stk = mysqli_fetch_assoc($result_stk);
									$stock_item_id  = $row_stk['stock_item_id'];

									$query_stk_adj_items = "INSERT INTO `stock_adjustment_items` (`company_id`,`stock_adj_id`, 
									`date`, `stock_item_id`, `warehouse_id`, `batch_no`, `expiry_date`, `qty_in`, `created_by`, 
									`created_datetime`, `branch_id`) VALUES ('$company_id','$stock_adj_id','$date','$stock_item_id','$store',
									'$batch_no','$expiry_date','$qty_in','$user_id', NOW(),'$branch_id')";
									mysqli_query($con, $query_stk_adj_items);
								};
							};
							fclose($csvFile);
						};
						$qstring = '?status=succ';
					} 
					else 
					{
						$qstring = '?status=err';
					};
				} 
				else 
				{
					$qstring = '?status=invalid_file';
				};

				header('Location: '.$_SERVER['DOCUMENT_ROOT'] .'/layout/vouchers/stock_adjustment_import_modal.php'.$qstring);
			};
		}

