		function stock_take_item_search_in_invoice()
		{
			global $con;
			$search = $_POST['search'];
			$criteria = $_POST['criteria'];
			$company_id = $_SESSION['company_id'];
			$warehouse_id = $_SESSION['warehouse_id'];
			$branch_id = $_SESSION['branch_id'];
			$user_id = $_SESSION['user_id'];
			$start_date = date('2000-01-01');
			$end_date = date('Y-m-d');
			$value = "";
			$i = 0;
			if($criteria=='ITEM_NAME')
			{
				$query = "SELECT * FROM stock_items WHERE company_id = '$company_id' AND 
				stock_item LIKE '%".$search."%' ORDER BY stock_item ASC";
			}
			else if($criteria=='ITEM_NUMBER')
			{
				$query = "SELECT * FROM stock_items WHERE company_id = '$company_id' AND 
				code LIKE '%".$search."%' ORDER BY stock_item ASC";
			}
			else if($criteria=='BARCODE')
			{
				$query = "SELECT * FROM stock_items WHERE company_id = '$company_id' AND 
				barcode LIKE '%".$search."%' ORDER BY stock_item ASC";
			};
			$query_run = mysqli_query($con, $query);
				
			$value .= '<table class="table table-hover table-bordered table-sm" id="stock_sales_items_list_table" width="100%" cellspacing="0">
				<thead>
					<tr>
						<th width="70%">Item</th>
						<th width="15%" class = "action-td">Price</th>
						<th width="15%" class = "action-td">Store Qty</th>
					</tr>
				</thead>
				<tbody class="pv-table-body">';

				if (!empty($query_run) && mysqli_num_rows($query_run) > 0)
				{
					while($row = mysqli_fetch_assoc($query_run))
					{
						$i++;
						$stock_item_id = $row['stock_item_id'];
						$query_bal = "SELECT item_id, SUM(ob) AS ob, SUM(qty_in) AS qty_in, SUM(qty_out) AS qty_out FROM
						(SELECT stock_item_id  AS item_id, warehouse_id, 0 AS ob, 0 AS qty_out, qty AS qty_in FROM stock_purchase_items 
						WHERE date BETWEEN '$start_date' AND '$end_date' AND warehouse_id = '$warehouse_id' AND stock_item_id = '$stock_item_id'
						UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 AS ob,  qty AS qty_out, 0 AS qty_in FROM stock_sales_items 
						WHERE date BETWEEN '$start_date' AND '$end_date' AND warehouse_id = '$warehouse_id' AND stock_item_id = '$stock_item_id'
						UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 AS ob,  qty_out AS qty_out, 0 AS qty_in FROM stock_adjustment_items 
						WHERE date BETWEEN '$start_date' AND '$end_date' AND warehouse_id = '$warehouse_id' AND stock_item_id = '$stock_item_id'
						UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 AS ob,  qty_transferred AS qty_out, 0 AS qty_in FROM stock_transfer_items 
						WHERE date_trans BETWEEN '$start_date' AND '$end_date' AND warehouse_id = '$warehouse_id' AND stock_item_id = '$stock_item_id'
						UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 AS ob,  0 AS qty_out, qty_in AS qty_in FROM stock_adjustment_items 
						WHERE date BETWEEN '$start_date' AND '$end_date' AND warehouse_id = '$warehouse_id' AND stock_item_id = '$stock_item_id'
						UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 AS ob,  0 AS qty_out, qty_received AS qty_in FROM stock_transfer_items 
						WHERE date_trans BETWEEN '$start_date' AND '$end_date' AND warehouse_id = '$warehouse_id' AND stock_item_id = '$stock_item_id') AS c GROUP BY item_id";

						$query_run_bal = mysqli_query($con, $query_bal);

						if (mysqli_num_rows($query_run_bal) > 0)
						{
							$row_bal = mysqli_fetch_assoc($query_run_bal);
							$balance = $row_bal['ob']+$row_bal['qty_in']-$row_bal['qty_out'];
						}
						else
						{
							$balance = 0;
						};

						$value .= '<tr id="'.$i.'">
							<th>
								<small><a href="#" id="btn_add_qty_stock_take_invoice_item" 
									data-id="'.$row['stock_item_id'].'"
									data-id1="'.$row['stock_item'].'"
									data-id2="'.$row['price_cash'].'"
									data-id3="'.$row['maintain_batch'].'"
									data-id4="'.$row['block_negative'].'"
									data-id5="'.$balance.'">
								'.$row['stock_item'].'</a></small>
							</th>
							<th class="amt-td">
								<small>'.$row['price_cash'].'</small>
							</th>
							<th class="action-td">
								<small>'.$balance.'</small>
							</th>
						</tr>';
					};
				}
				else
				{
					$value .= 'No Stock Sales Not Found';
				};
			$value .= '</tbody>
			</table>';
			echo $value;
		}

		function stock_take_invoice_add_qty()
		{
			global $con;
			$stock_item_id = $_POST['stock_item_id'];
			$maintain_batch = $_POST['maintain_batch'];
			$block_negative = $_POST['block_negative'];
			$warehouse_id = $_POST['warehouse_id'];
			$start_date = date('2000-01-01');
			$end_date = date('Y-m-d');
			$data = array();
			$value = "";
			$select = '<label for="stock_take_batch_qty_batch_no">Batch/Lot Number</label>
			<select class="form-control bg-light text-center" name="stock_take_batch_qty_batch_no" id="stock_take_batch_qty_batch_no">
				<option value="0" data-id="0">Please select</option>';
			$batch_list = "";
			$i = 0;

			$query = "SELECT * FROM stock_purchase_items WHERE stock_item_id = '$stock_item_id' AND 
			warehouse_id = '$warehouse_id' GROUP BY batch ASC";
			$query_run = mysqli_query($con, $query);

			$value .= '<table table class="table table-hover table-bordered table-sm" width="100%" cellspacing="0" style="font-size: 14px" id="stock_take_invoice_batch_qty_batch_expiry_table">
				<tr>
					<th colspan="4" class="action-td">BATCH LIST</th>
				</tr>
				<tr>
					<th width="40%" class="action-td">Batch/Lot Number</th>
					<th width="20%" class="action-td">Batch Qty</th>
					<th width="20%" class="action-td">Expiry Date</th>
					<th width="20%" class="action-td">Days to Expire</th>
				</tr>';

				if (!empty($query_run) && mysqli_num_rows($query_run) > 0)
				{
					while($row = mysqli_fetch_assoc($query_run))
					{
						$i++;
						$batch = $row['batch'];
						$query_bal = "SELECT item_id, SUM(ob) AS ob, SUM(qty_in) AS qty_in, SUM(qty_out) AS qty_out FROM
						(SELECT stock_item_id  AS item_id, warehouse_id, 0 AS ob, 0 AS qty_out, qty AS qty_in FROM stock_purchase_items 
						WHERE date BETWEEN '$start_date' AND '$end_date' AND warehouse_id = '$warehouse_id' AND stock_item_id = '$stock_item_id' AND batch = '$batch'
						UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 AS ob,  qty AS qty_out, 0 AS qty_in FROM stock_sales_items 
						WHERE date BETWEEN '$start_date' AND '$end_date' AND warehouse_id = '$warehouse_id' AND stock_item_id = '$stock_item_id' AND batch = '$batch'
						UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 AS ob,  qty_out AS qty_out, 0 AS qty_in FROM stock_adjustment_items 
						WHERE date BETWEEN '$start_date' AND '$end_date' AND warehouse_id = '$warehouse_id' AND stock_item_id = '$stock_item_id' AND batch_no = '$batch'
						UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 AS ob,  qty_transferred AS qty_out, 0 AS qty_in FROM stock_transfer_items 
						WHERE date_trans BETWEEN '$start_date' AND '$end_date' AND warehouse_id = '$warehouse_id' AND stock_item_id = '$stock_item_id' AND batch_no = '$batch'
						UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 AS ob,  0 AS qty_out, qty_in AS qty_in FROM stock_adjustment_items
						WHERE date BETWEEN '$start_date' AND '$end_date' AND warehouse_id = '$warehouse_id' AND stock_item_id = '$stock_item_id' AND batch_no = '$batch'
						UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 AS ob,  0 AS qty_out, qty_received AS qty_in FROM stock_transfer_items
						WHERE date_trans BETWEEN '$start_date' AND '$end_date' AND warehouse_id = '$warehouse_id' AND stock_item_id = '$stock_item_id' AND batch_no = '$batch') AS c GROUP BY item_id";

						$query_run_bal = mysqli_query($con, $query_bal);

						if (mysqli_num_rows($query_run_bal) > 0)
						{
							$row_bal = mysqli_fetch_assoc($query_run_bal);
							$balance = $row_bal['ob']+$row_bal['qty_in']-$row_bal['qty_out'];
						}
						else
						{
							$balance = 0;
						};

						if($balance > 0)
						{
							$expiry = $row['expiry_date'];
							$today = date('Y-m-d');
							$select .= '<option value="'.$batch.'" data-id="'.$balance.'" data-id1="'.$expiry.'">'.$batch.'</option>';

							$startTimeStamp = strtotime($today);
							$endTimeStamp = strtotime($expiry);
							$timeDiff = abs($endTimeStamp - $startTimeStamp);
							$numberDays = $timeDiff/86400;
							$numberDays = intval($numberDays);

							//<tr>
								if($numberDays < 31)
								{
									$value .='<tr id="'.$i.'" style="background:salmon; color:black">';
								}
								else if($numberDays > 30 && $numberDays < 91)
								{
									$value .='<tr id="'.$i.'" style="background:lightyellow; color:black">';
								}
								else if($numberDays > 90)
								{
									$value .='<tr id="'.$i.'" style="color:black">';
								};
								$value .='<td class="action-td">'.$batch.'</td>
								<td class="action-td">'.$balance.'</td>
								<td class="action-td">'.$row['expiry_date'].'</td>
								<td class="action-td">'.$numberDays.'</td>
							</tr>';
						};
					};
				}
				else
				{
					$value .= 'No Batches Found';
				};
				
				$select .= '</select>';
				if($maintain_batch == 'Yes' && mysqli_num_rows($query_run) > 0)
				{
					$batch_list = $select;
				}
				else
				{
					$batch_list = '<label for="stock_take_batch_qty_batch_no">Batch/Lot Number</label>
					<input type="text" name="stock_take_batch_qty_batch_no" class="form-control bg-light text-center" id="stock_take_batch_qty_batch_no">';
				};
			$value .= '</tbody>
			</table>';

			array_push($data, $value, $batch_list);
			echo json_encode($data);
		}

