		function nhis_set_principal_gdrg()
		{
			global $con;
			$Principal_nhis_id = $_POST['Principal_nhis_id'];
			$nhis_details = array();
			
			$query_nhis = "SELECT * FROM nhis WHERE nhis_id ='$Principal_nhis_id'";
			$result_nhis = mysqli_query($con,$query_nhis);

			if(!empty($result_nhis) && mysqli_num_rows($result_nhis) > 0)
			{
				$row_nhis = mysqli_fetch_assoc($result_nhis);
				if($_SESSION['age'] > 11)
				{
					$code = $row_nhis['gdrg_adult'];
					$price = $row_nhis['price_adult'];
				}
				else
				{
					$code = $row_nhis['gdrg_child'];
					$price = $row_nhis['price_child'];
				};
			}
			else
			{
				$code = 'N/A';
			};

			array_push($nhis_details, $code, $price);
			echo json_encode($nhis_details);
		}
		
